insert into public.mushroom_lookalikes (edible_slug, lookalike_slug, confusion_risk, key_differences, visual_differences, smell_differences, habitat_differences, spore_print_differences, pro_tip, source)
values
($l1$agaricus_campestris$l1$,$l1$agaricus_moelleri$l1$,$l1$mittel$l1$,array[$l1$Perlhuhn-/Karbol-Champignon riecht unangenehm nach Karbol/Tinte/Jod (Apotheke, Krankenhaus), beim Erhitzen widerlich verstaerkt; Wiesen-Champignon riecht angenehm pilzig-mild$l1$,$l1$Stielbasis des Perlhuhn-Champignons verfaerbt sich beim Kratzen/Anschneiden sofort kraeftig chromgelb (besonders im Knollenbereich); Wiesen-Champignon hoechstens schwach roetlich/braeunlich$l1$,$l1$Wiesen-Champignon hat von Anfang an rosa, spaeter schokobraune Lamellen (nie reinweiss); reinweisse Lamellen bei jungem Champignon = Warnsignal Richtung Gift-Champignon$l1$,$l1$Hutoberflaeche des Perlhuhn-Champignons graubraun gefleckt/schuppig (perlhuhnartig genattert); Wiesen-Champignon reinweiss bis cremefarben, glatt bis schuppig$l1$,$l1$Karbolgeruch UND chromgelbe Stielbasis treten zusammen auf und schliessen jeden Speise-Champignon sicher aus$l1$]::text[],$l1$Perlhuhn-Champignon mit graubraun geflecktem, perlhuhnartig genattertem Hut; Wiesen-Champignon reinweiss bis creme, glatt. Achtung: beide klein-mittelgross, im Feld leicht verwechselbar.$l1$,$l1$Giftpilz: Karbol/Tinte/Jod, beim Kochen widerlich verstaerkt. Wiesen-Champignon: angenehm pilzig-mild. Geruch ist hier ein zuverlaessiges Trennmerkmal.$l1$,$l1$Perlhuhn-Champignon eher in Parks, Gaerten, an Waldraendern und in Siedlungsnaehe; Wiesen-Champignon auf gemaehten Wiesen und Weiden. Habitat-Ueberlappung moeglich, daher nicht allein verlassen.$l1$,$l1$Beide schokoladenbraunes Sporenpulver - KEIN Unterscheidungsmerkmal.$l1$,$l1$Bei JEDEM Champignon Stielbasis anschneiden UND riechen: chromgelbes Anlaufen plus Karbol-/Tintengeruch (auch beim kurzen Anbraten testen) = Gift-Champignon, kompletter Korb-Inhalt verwerfen, nicht nur das Einzelexemplar.$l1$,$l1$123pilze, pilzkurse.com (Schweiz/VAPKO-nah), DGfM, Wikipedia Karbol-Champignon, pilzbuch-pilzwelten.de$l1$),
($l1$agaricus_silvicola$l1$,$l1$agaricus_moelleri$l1$,$l1$mittel$l1$,array[$l1$Duennfleischiger Anis-Egerling riecht deutlich nach Anis/Bittermandel (angenehm); Perlhuhn-Champignon nach Karbol/Tinte/Jod (unangenehm)$l1$,$l1$Stielbasis des Anis-Egerlings laeuft beim Schneiden hoechstens schwach gelblich an; die des Perlhuhn-Champignons sofort kraeftig chromgelb$l1$,$l1$Beim Erhitzen wird der Anis-Duft angenehm suesslich, der Perlhuhn-Champignon stinkt verstaerkt nach Tinte/Karbol$l1$,$l1$Anis-Egerling hat reinweissen, seidigen Hut (gilbt auf Druck leicht gelb); Perlhuhn-Champignon graubraun gefleckt/schuppig$l1$,$l1$Beide haben jung helle Lamellen - daher NIE an der Lamellenfarbe allein entscheiden, sondern Geruch + Stielbasis-Reaktion kombinieren$l1$]::text[],$l1$Anis-Egerling reinweiss seidig (gilbt schwach); Perlhuhn-Champignon graubraun gefleckt mit perlhuhnartiger Hutnatterung. Cave: weisslicher Habitus aehnlich.$l1$,$l1$Anis-Egerling: angenehm nach Anis/Bittermandel. Giftpilz: Karbol/Tinte/Jod, beim Kochen widerlich. Geruch ist das wichtigste Trennmerkmal.$l1$,$l1$Anis-Egerling im Nadel-/Mischwald; Perlhuhn-Champignon in Parks, Gaerten, an Waldraendern. Habitat hilft, ist aber nicht absolut trennscharf.$l1$,$l1$Beide schokoladenbraun - KEIN Unterscheidungsmerkmal.$l1$,$l1$Riech- und Kratzprobe an der Stielbasis ist Pflicht: Karbolgeruch plus chromgelbe Basis = giftig, nie essen. Anis-Geruch ohne chromgelbe Basis spricht fuer den Anis-Egerling - im Zweifel Sporenbild und Fachperson hinzuziehen.$l1$,$l1$123pilze, pilzkurse.com (Schweiz), pilzbuch-pilzwelten.de, DGfM$l1$),
($l1$agaricus_augustus$l1$,$l1$agaricus_moelleri$l1$,$l1$mittel$l1$,array[$l1$Riesen-Champignon (Schiefknolliger Anis-Egerling) riecht angenehm nach Anis/Bittermandel; Perlhuhn-Champignon nach Karbol/Tinte$l1$,$l1$Stielbasis des Perlhuhn-Champignons laeuft sofort kraeftig chromgelb an; Riesen-Champignon gilbt nur schwach/aussen$l1$,$l1$Riesen-Champignon mit braeunlich-schuppigem (nicht graufleckigem) Hut, der auf Druck angenehm gilbt; Perlhuhn-Champignon graubraun perlhuhnartig gefleckt$l1$,$l1$Beim Erhitzen Anis-Duft (essbar) vs Tinten-/Karbolgeruch (giftig)$l1$,$l1$Riesen-Champignon wird sehr gross (Hut oft 10-25 cm); auffaellige Groesse allein ist aber KEIN Sicherheitsbeweis - Geruch + Stielbasis bleiben Pflicht$l1$]::text[],$l1$Riesen-Champignon mit braeunlich-schuppigem, auf Druck gilbendem Hut, gross; Perlhuhn-Champignon graubraun gefleckt, perlhuhnartig, kleiner.$l1$,$l1$Riesen-Champignon: Anis/Bittermandel. Perlhuhn-Champignon: Karbol/Tinte, beim Kochen widerlich. Geruch ist das zentrale Trennmerkmal.$l1$,$l1$Riesen-Champignon an Wegraendern, im Nadelwald, auf Kompost; Perlhuhn-Champignon Parks/Gaerten/Waldrand. Ueberlappung in Siedlungsnaehe moeglich.$l1$,$l1$Beide schokoladenbraun - KEIN Unterscheidungsmerkmal.$l1$,$l1$Karbolgeruch und chromgelbe Stielbasis sind das untruegliche Zeichen fuer den Giftpilz - im Zweifel den gesamten Fund wegwerfen, nicht auf die Groesse verlassen.$l1$,$l1$123pilze, pilzbuch-pilzwelten.de, DGfM, pilzkurse.com (Schweiz)$l1$),
($l1$amanita_caesarea$l1$,$l1$amanita_muscaria$l1$,$l1$hoch$l1$,array[$l1$Fliegenpilz hat REINWEISSE Lamellen, weissen Stiel und weissen Ring - Kaiserling hat GELBE Lamellen, gelben Stiel und gelben Ring$l1$,$l1$Fliegenpilz hat eine warzige Knolle mit Warzenguerteln; Kaiserling eine dickhaeutige, sackartige, lappige weisse Volva (Eierschalen-Scheide)$l1$,$l1$Fliegenpilzhut traegt weisse, abwaschbare Flocken (Velumreste); Kaiserlinghut ist glatt orangerot ohne Flockenmuster$l1$,$l1$GEFAHR: vom Regen ausgewaschener oder verblasster Fliegenpilz verliert die weissen Flocken und kann orange wirken - dann allein Lamellen-/Stiel-/Ring-Farbe (weiss!) und die warzige Knolle entscheiden$l1$,$l1$Kaiserling in der Schweiz ausgesprochene Raritaet (nur warme Suedlagen, v.a. Tessin) - ein orangeroter Amanita ausserhalb solcher Lagen ist mit hoher Wahrscheinlichkeit Fliegenpilz$l1$]::text[],$l1$Kaiserling durchgehend gelb (Lamellen/Stiel/Ring) mit sackartiger weisser Volva und glattem orangerotem Hut; Fliegenpilz weiss (Lamellen/Stiel/Ring) mit warziger Knolle und (ggf. ausgewaschenen) Huthautflocken.$l1$,$l1$Beide unauffaellig-mild - Geruch ist KEIN Unterscheidungsmerkmal.$l1$,$l1$Kaiserling waermeliebend, in der Schweiz nur in Suedlagen (Tessin) extrem selten; Fliegenpilz haeufig bei Birke/Fichte im ganzen Land.$l1$,$l1$Beide weisses Sporenpulver - KEIN Unterscheidungsmerkmal.$l1$,$l1$Niemals einen orangeroten Pilz essen, ohne Lamellen, Stiel UND Ring zu pruefen: alles weiss = Fliegenpilz (giftig). Nur durchgehend GELBE Lamellen/Stiel/Ring plus sackartige weisse Volva sprechen fuer den Kaiserling - im Zweifel Fachperson/Pilzkontrolle (VAPKO).$l1$,$l1$awl.ch, pilzkurse.com (Schweiz), Wikipedia Fliegenpilz, fungiversum.de$l1$),
($l1$amanita_crocea$l1$,$l1$amanita_gemmata$l1$,$l1$hoch$l1$,array[$l1$Narzissengelber Wulstling hat eine zwiebelartige Knolle mit gerandeter, vergaenglicher Scheide UND einen (oft fluechtigen) Ring - Scheidenstreiflinge (inkl. Orangegelber Scheidenstreifling) haben NIE einen Ring$l1$,$l1$Scheidenstreifling besitzt eine hohe, hautige, freie Scheide (Volva) am Stielgrund, keine Knolle; Hutrand deutlich gerieft/gefurcht$l1$,$l1$Hut des Giftpilzes traegt weisse, eckige Velumreste (Hautflocken) und ist satt- bis blassgelb (kann bei Trockenheit ausbleichen); Scheidenstreifling-Hut orangegelb, flockenfrei, mit gerieftem Rand$l1$,$l1$Stiel des Scheidenstreiflings ohne haengende Ringmanschette; jeder geringelte gelbe Amanita ist verdaechtig$l1$,$l1$Wichtig: ausgeblichene gemmata-Huete koennen blasser/aehnlicher wirken - daher IMMER auf Ring + Knollenform achten, nicht nur auf Hutfarbe$l1$]::text[],$l1$Giftpilz: gelblicher Hut mit weissen Flockenresten, (fluechtiger) Ring am Stiel, zwiebelartige Knolle mit gerandeter Scheide. Scheidenstreifling: orangegelber, gerieft-randiger, flockenfreier Hut, KEIN Ring, hohe freie Scheide.$l1$,$l1$Beide unauffaellig - Geruch ist KEIN Unterscheidungsmerkmal.$l1$,$l1$Beide bei Laub-/Nadelbaeumen auf eher saurem Boden; Habitat trennt nicht zuverlaessig.$l1$,$l1$Beide weisses Sporenpulver - KEIN Unterscheidungsmerkmal.$l1$,$l1$Scheidenstreiflinge haben NIE einen Ring und nie eine gerandete Knolle - jeder gelbe Amanita MIT Ringmanschette und/oder Knolle ist verdaechtig (Narzissengelber Wulstling enthaelt Ibotensaeure/Muscimol und Muscarin) und gehoert nicht in den Korb.$l1$,$l1$123pilze, pilzbuch-pilzwelten.de, tintling.com, DGfM, ultimate-mushroom.com$l1$),
($l1$amanita_fulva$l1$,$l1$amanita_gemmata$l1$,$l1$hoch$l1$,array[$l1$Rotbrauner Scheidenstreifling ist RINGLOS - Narzissengelber Wulstling hat einen (oft fluechtigen) haengenden Ring$l1$,$l1$Scheidenstreifling mit hoher, freier, rotbraun gefleckter Scheide (Volva) am Stielgrund statt zwiebelartiger Knolle mit gerandeter Scheide$l1$,$l1$Hut des Scheidenstreiflings rotbraun bis fuchsig, glatt, stark gerieft am Rand, ohne Velumflocken; Giftpilz gelb (bei Trockenheit ausgeblichen) mit weissen Hautflocken$l1$,$l1$Stiel des Scheidenstreiflings ohne genatterte Ringzone und ohne Manschette$l1$,$l1$Rotbrauner Scheidenstreifling sollte ohnehin nur gut durchgegart gegessen werden - roh sind Streiflinge unvertraeglich$l1$]::text[],$l1$Scheidenstreifling rotbraun, gerieft, flockenfrei, ringlos, mit hoher Scheide; Giftpilz gelblich, flockig, mit (fluechtigem) Ring und gerandeter Knolle.$l1$,$l1$Beide unauffaellig - KEIN Unterscheidungsmerkmal.$l1$,$l1$Beide bei Laub-/Nadelbaeumen auf eher saurem Boden; Habitat trennt nicht.$l1$,$l1$Beide weisses Sporenpulver - KEIN Unterscheidungsmerkmal.$l1$,$l1$Auf Ring und Knolle achten: Scheidenstreiflinge sind immer ringlos mit hoher freier Scheide; ein gelber Amanita mit Ring oder gerandeter Knolle ist der giftige Narzissengelbe Wulstling - im Zweifel stehen lassen.$l1$,$l1$123pilze, pilzbuch-pilzwelten.de, tintling.com, first-nature.com$l1$),
($l1$amanita_rubescens$l1$,$l1$amanita_gemmata$l1$,$l1$hoch$l1$,array[$l1$Perlpilz roetet bei Verletzung/Madenfrass deutlich weinrot/fleischrosa - Narzissengelber Wulstling roetet NIE, sein Fleisch bleibt weiss-gelblich (zuverlaessigstes Trennmerkmal)$l1$,$l1$Perlpilz hat einen kraeftigen, oberseits gerieften (gerillten) Ring; der Ring des Giftpilzes ist duenn und vergaenglich (oft fehlend)$l1$,$l1$Hutfarbe Perlpilz sehr variabel (weisslich, braungelblich, fleischrosa bis rotbraun) - daher NICHT allein auf Farbe verlassen; Giftpilz meist satt zitronen-/ockergelb, bei Trockenheit ausbleichend$l1$,$l1$Knolle des Perlpilzes rundlich mit Velumguerteln (ohne gerandete Scheide); Giftpilz mit zwiebeliger Knolle und gerandeter Restscheide$l1$,$l1$Stielbasis/Fraßstellen des Perlpilzes oft rosa/weinrot angelaufen, beim Giftpilz nicht$l1$]::text[],$l1$Perlpilz mit rosa Roetung an Druck-/Fraßstellen und kraeftig gerieftem Ring (Hutfarbe variabel); Giftpilz meist leuchtend gelb, nicht roetend, mit fluechtigem Ring.$l1$,$l1$Beide unauffaellig-mild - KEIN verlaessliches Unterscheidungsmerkmal.$l1$,$l1$Beide im Laub-/Nadelwald; Habitat trennt nicht.$l1$,$l1$Beide weisses Sporenpulver - KEIN Unterscheidungsmerkmal.$l1$,$l1$Der Perlpilz MUSS roeten und ist nur gut durchgegart geniessbar - ein gelber, NICHT roetender Wulstling gehoert nie in den Korb (Narzissengelber Wulstling: Ibotensaeure/Muscimol und Muscarin). Roh ist auch der Perlpilz giftig.$l1$,$l1$123pilze, pilzbuch-pilzwelten.de, DGfM, fungiversum.de$l1$),
($l1$steinpilz$l1$,$l1$caloboletus_calopus$l1$,$l1$mittel$l1$,array[$l1$Schoenfuss-Roehrling schmeckt extrem BITTER (auch nach dem Kochen bitter, ungeniessbar) - Steinpilz schmeckt mild-nussig$l1$,$l1$Schoenfuss-Roehrling blaut bei Verletzung an Fleisch und Roehren rasch blaugruenlich; Steinpilzfleisch bleibt weiss und unveraenderlich (blaut nicht)$l1$,$l1$Stiel des Schoenfuss-Roehrlings kraeftig rot mit feinem Netz (unten rot, oben gelb); Steinpilzstiel braun-beige mit hellem Netz, NIE rot$l1$,$l1$Hut des Schoenfuss-Roehrlings lehmgrau/graubraun; Steinpilz warm braun bis kastanienbraun$l1$,$l1$Roehren/Poren des Steinpilzes weiss bis gelbgruen ohne Blauen; beim Giftpilz gelb und auf Druck blauend$l1$]::text[],$l1$Schoenfuss-Roehrling: lehmgrauer Hut, knallroter Netzstiel, blauendes Fleisch. Steinpilz: brauner Hut, beiger Netzstiel, weiss bleibendes Fleisch.$l1$,$l1$Steinpilz angenehm pilzig; Schoenfuss-Roehrling unauffaellig - der bittere Geschmack entscheidet.$l1$,$l1$Beide im Nadel-/Laubmischwald; Habitat trennt nicht zuverlaessig.$l1$,$l1$Beide olivbraunes Sporenpulver - KEIN Unterscheidungsmerkmal.$l1$,$l1$Geschmacksprobe (winziges Stueck Roehrenschicht auf die Zunge, NICHT schlucken, ausspucken): bitter plus rotes Stielnetz plus Blauen = Schoenfuss-Roehrling (magen-darm-giftig/ungeniessbar), kein Steinpilz.$l1$,$l1$awl.ch, pilzkurse.com (Schweiz), Wikipedia Schoenfuss-Roehrling, pilzbuch-pilzwelten.de$l1$),
($l1$butyriboletus_appendiculatus$l1$,$l1$caloboletus_calopus$l1$,$l1$mittel$l1$,array[$l1$Schoenfuss-Roehrling schmeckt stark BITTER (bleibt auch gekocht bitter) - Anhaengselroehrling schmeckt mild und angenehm$l1$,$l1$Hut des Anhaengselroehrlings warm braun bis ledergelb; Schoenfuss-Roehrling lehmgrau/graubraun$l1$,$l1$Anhaengselroehrling blaut nur schwach/langsam; Schoenfuss-Roehrling blaut rasch und kraeftig blaugruen$l1$,$l1$Anhaengselroehrling-Stiel gelb mit feinem gelbem Netz und wurzelndem Fortsatz; Schoenfuss-Roehrling-Stiel unten kraeftig rot genetzt$l1$,$l1$Fleisch des Anhaengselroehrlings goldgelb und mild; beim Schoenfuss bitter$l1$]::text[],$l1$Anhaengselroehrling: brauner Hut, gelber Stiel mit gelbem Netz, schwaches Blauen. Schoenfuss-Roehrling: grauer Hut, rot-gelber Netzstiel, kraeftiges Blauen.$l1$,$l1$Beide unauffaellig - der bittere Geschmack ist das entscheidende Trennmerkmal.$l1$,$l1$Beide waermeliebend im Laub-/Mischwald (Eiche/Buche); Habitat trennt nicht.$l1$,$l1$Beide olivbraunes Sporenpulver - KEIN Unterscheidungsmerkmal.$l1$,$l1$Geschmacksprobe (winziges Stueck, ausspucken): jeder bittere Roehrling fliegt aus dem Korb - der milde Anhaengselroehrling ist nie bitter. Bei rotem Stielnetz plus kraeftigem Blauen besonders kritisch pruefen.$l1$,$l1$pilzkurse.com (Schweiz), pilzbuch-pilzwelten.de, awl.ch$l1$),
($l1$suillellus_luridus$l1$,$l1$caloboletus_calopus$l1$,$l1$mittel$l1$,array[$l1$Schoenfuss-Roehrling schmeckt stark BITTER (ungeniessbar/magen-darm-giftig auch gekocht); Netzstieliger Hexen-Roehrling mild, aber NUR gut durchgegart essbar (roh giftig)$l1$,$l1$Netzstieliger Hexen-Roehrling hat ROTORANGE Poren und eine roetliche Linie (Batsch-Linie) ueber den Roehren; Schoenfuss-Roehrling gelbe Poren$l1$,$l1$Hexen-Roehrling-Hut oliv-/lederbraun, oft polsterfoermig; Schoenfuss-Roehrling lehmgrau$l1$,$l1$Beide blauen stark - aber Hexen-Roehrling mit roten Poren und rotem Netz auf braeunlich-gelbem Stiel, Schoenfuss-Roehrling mit gelben Poren und rot-gelbem Stiel$l1$,$l1$Geschmack entscheidet: Schoenfuss bitter (raus); Netzstieliger Hexen-Roehrling mild und erst nach ausreichendem Durchgaren essbar$l1$]::text[],$l1$Netzstieliger Hexen-Roehrling: rotorange Poren, rotes Stielnetz, Batsch-Linie. Schoenfuss-Roehrling: gelbe Poren, grauer Hut, rot-gelber Netzstiel.$l1$,$l1$Beide unauffaellig - der Bittergeschmack des Schoenfuss-Roehrlings ist das Trennmerkmal.$l1$,$l1$Beide bei Laubbaeumen; Netzstieliger Hexen-Roehrling bevorzugt kalkhaltigen Boden. Habitat trennt nicht zuverlaessig.$l1$,$l1$Beide olivbraunes Sporenpulver - KEIN Unterscheidungsmerkmal.$l1$,$l1$Poren pruefen UND Geschmacksprobe (ausspucken): gelbe Poren plus bitter = Schoenfuss-Roehrling (raus); rote/orange Poren ohne Bitterkeit = Netzstieliger Hexen-Roehrling - dieser ist roh giftig und nur gut durchgegart essbar, nie roh probieren ausser zur Spuck-Geschmacksprobe.$l1$,$l1$pilzkurse.com (Schweiz), Wikipedia Schoenfuss-Roehrling, awl.ch, pilzbuch-pilzwelten.de$l1$),
($l1$kuehneromyces_mutabilis$l1$,$l1$conocybe_filaris$l1$,$l1$sehr_hoch_lebensgefahr$l1$,array[$l1$Stockschwämmchen: Stiel unter dem Ring deutlich braun, abstehend-schuppig/genattert — Nadelholz-Häubling (Conocybe filaris/Pholiotina rugosa): Stiel glatt bis silbrig-längsfaserig, ohne Schuppen. Das Stiel-Merkmal ist der wichtigste Trennfaktor.$l1$,$l1$Der Häubling enthält Amatoxine (dasselbe Gift wie der Knollenblätterpilz) — bereits wenige Hüte können tödliches Leberversagen auslösen, mit 6-24h symptomfreier Latenz vor dem Organschaden.$l1$,$l1$Der Häubling wächst meist terrestrisch auf Rasen, Wiesen, Holzhäcksel, Komposterde und Nadelstreu am Boden — das Stockschwämmchen büschelig direkt auf morschem Laub-/Nadelholz (Stümpfe, liegende Stämme).$l1$,$l1$Stockschwämmchen wächst typisch in dichten Büscheln am selben Holz; der Häubling steht meist einzeln bis gesellig am Boden, nicht büschelig aus Holz.$l1$,$l1$Hut des Stockschwämmchens trocknet typisch zweifarbig (hygrophaner Wasser-Saum) ab; der Häubling-Hut ist gleichmäßiger ocker-zimtbraun und kaum zweifarbig gezont.$l1$]::text[],$l1$Entscheidend ist der Stiel unterhalb des Rings: braun abstehend-schuppig (Stockschwämmchen) gegen glatt bis silbrig-längsfaserig (Häubling). Die Hutfarben sind bei beiden honig- bis zimtbraun und NICHT trennend.$l1$,$l1$Stockschwämmchen riecht angenehm pilzig-aromatisch; der Häubling ist geruchlich unauffällig bis leicht mehlig — Geruch ist KEIN sicheres Trennmerkmal.$l1$,$l1$Stockschwämmchen büschelig auf morschem Laub-/Nadelholz (Stümpfe, Totholz); Conocybe filaris terrestrisch auf Rasen, Wiesen, Holzhäcksel, Kompost und Nadelstreu am Boden — Wuchsort (Holz vs. Boden) ist ein wichtiges Indiz, aber allein nicht beweisend.$l1$,$l1$Beide rostbraun bis zimtbraun — als Trennmerkmal UNBRAUCHBAR. Daher zwingend die Stiel-Schuppung unter dem Ring prüfen.$l1$,$l1$Stockschwämmchen NUR sammeln, wenn der Stiel unter dem Ring eindeutig braun beschuppt/genattert ist UND der Pilz büschelig auf Holz wächst. Bei glattem/silbrigfaserigem Stiel oder Bodenwuchs auf Rasen sofort verwerfen — Lebensgefahr durch Amatoxine. Im Zweifel zur Pilzkontrolle (VAPKO).$l1$,$l1$GiftnotrufZentrale (gizbonn.de), 123pilze, DGfM, healing-mushrooms.net (Pholiotina rugosa)$l1$),
($l1$zigeunerpilz$l1$,$l1$cortinarius_splendens$l1$,$l1$sehr_hoch_lebensgefahr$l1$,array[$l1$Zigeunerpilz (Reifpilz, Cortinarius caperatus): Hut graubräunlich/ockerlich mit weißlich-bereiftem Schimmer, NICHT leuchtend gelb — Cortinarius splendens: kräftig schwefel- bis leuchtendgelb in allen Teilen.$l1$,$l1$Reifpilz hat einen echten häutigen Stielring; der Schöngelbe Klumpfuß hat nur eine flüchtige gelbe Cortina (Spinnwebschleier), KEINEN festen häutigen Ring.$l1$,$l1$Cortinarius splendens hat eine gerandete gelbe Knolle und gelbes Fleisch; der Reifpilz hat eine schwach knollige Basis ohne leuchtendes Gelb.$l1$,$l1$Der Schöngelbe Klumpfuß enthält ein nephrotoxisches Gift (Orellanin-Syndrom-Typ, chemisch noch nicht abschließend identifiziert — NICHT zwingend Orellanin selbst) und kann tödliches Nierenversagen mit tage- bis wochenlanger Latenz auslösen.$l1$,$l1$Reifpilz im sauren Nadel-/Mischwald und Heidelbeerbeständen; C. splendens als Mykorrhizapilz bevorzugt kalkreiche Laubwälder (besonders bei Buche).$l1$]::text[],$l1$Leuchtgelb = Warnsignal: jeder durchgehend schwefel-/leuchtendgelbe Schleierling ist tabu — der essbare Reifpilz ist matt grau-ocker-bräunlich mit bereiftem Hut und häutigem Ring.$l1$,$l1$Reifpilz aromatisch-pilzig; Cortinarius splendens unauffällig bis leicht rettichartig — Geruch trennt NICHT zuverlässig.$l1$,$l1$Reifpilz in sauren Nadel-/Mischwäldern und Heidelbeerbeständen; Schöngelber Klumpfuß als Mykorrhizapilz in kalkreichen Laubwäldern, typisch bei Buche.$l1$,$l1$Beide rostbraun — daher KEIN Trennkriterium. Auf Hutfarbe (leuchtgelb!), echten häutigen Ring und gerandete gelbe Knolle achten.$l1$,$l1$Kein Schleierling (Cortinarius) mit Rost-Sporenpulver für Anfänger — leuchtend gelbe Klumpfüße grundsätzlich stehen lassen. Das Nierengift wirkt erst nach Tagen, eine Vergiftung ist anfangs unbemerkt. Im Zweifel Pilzkontrolle (VAPKO).$l1$,$l1$123pilze (123pilzsuche.de), DGfM Vergiftungssyndrome, gifte.de, mycopedia.ch, Wikipedia (Leuchtendgelber Klumpfuß)$l1$),
($l1$clitopilus_prunulus$l1$,$l1$clitocybe_phyllophila$l1$,$l1$hoch$l1$,array[$l1$Mehlräsling riecht stark und eindeutig nach frischem Mehl/Gurke; Bleiweißer Trichterling riecht muffig-süßlich bis parfümiert — der Geruch ist ein wichtiges Bestätigungsmerkmal.$l1$,$l1$Sporenpulver des Mehlräslings rosa (Lamellen im Alter rosa-rötlich überlaufend); beim Bleiweißen Trichterling weiß bis cremefarben — das Sporenpulver ist das SICHERSTE Trennmerkmal.$l1$,$l1$Lamellen des Mehlräslings deutlich herablaufend und leicht ablösbar; beim Bleiweißen Trichterling nur schwach/dezent herablaufend.$l1$,$l1$Der Bleiweiße Trichterling wird als muscarinverdächtig/giftig geführt (Schweiß-/Speichel-/Tränenfluss-Syndrom; Toxingehalt in der Literatur umstritten, daher konservativ als giftig behandeln) — der Mehlräsling ist gefahrlos essbar.$l1$,$l1$Hut des Bleiweißen Trichterlings glasig-firnisartig weiß bereift; Mehlräsling matt grauweiß, oft etwas verbogen.$l1$]::text[],$l1$Beide klein und weiß; der Trichterling wirkt glasig/firnisartig bereift, der Mehlräsling matt-wildledrig — sicher trennt aber erst das Sporenpulver (rosa vs. weiß).$l1$,$l1$Mehlräsling = klarer Mehl-/Gurkengeruch; Bleiweißer Trichterling = muffig-süßlich/parfümiert. Der Mehlgeruch ist das wichtigste Bestätigungsmerkmal — allein aber nicht beweisend.$l1$,$l1$Beide in Laub-/Nadelwald; der Bleiweiße Trichterling oft truppweise in der Laub-/Nadelstreu, an Wegrändern und in Gärten.$l1$,$l1$Mehlräsling rosa, Bleiweißer Trichterling weiß/creme — der Sporenabwurf ist das sicherste Trennmerkmal. Bei Unsicherheit IMMER Sporenabwurf machen.$l1$,$l1$Mehlräsling nur bei eindeutigem Mehlgeruch UND rosa Sporenpulver verzehren — jeder weiß-sporige, parfümiert/muffig riechende weiße Trichterling ist muscarinverdächtig und bleibt stehen.$l1$,$l1$123pilze, pilzbuch-pilzwelten.de, mycopedia.ch, VAPKO, René Flammer (Giftpilze 2014)$l1$),
($l1$marasmius_oreades$l1$,$l1$clitocybe_phyllophila$l1$,$l1$hoch$l1$,array[$l1$Nelkenschwindling: Lamellen weit stehend, blass, NICHT herablaufend, Stiel zäh-biegsam (lässt sich verdrehen ohne zu brechen) — Bleiweißer Trichterling: Lamellen gedrängt und schwach herablaufend, Stiel brüchig.$l1$,$l1$Nelkenschwindling riecht würzig-süßlich (Nelke/Bittermandel); Bleiweißer Trichterling muffig-süßlich/parfümiert.$l1$,$l1$Weiße Trichterlinge (Clitocybe phyllophila und besonders die Wiesenarten C. rivulosa/dealbata) sind muscarinverdächtig/giftig — sie sind die klassische gefährliche Verwechslung weißhütiger Wiesenpilze.$l1$,$l1$Nelkenschwindling-Hut ledergelb-beige mit stumpfem Mittelbuckel und durchscheinend gerieftem Rand; weiße Trichterlinge glasig weiß bereift, oft niedergedrückt/trichterig.$l1$,$l1$Sicherheitsregel: Auf grasigen Standorten zusätzlich auf die gefährlicheren weißen Wiesen-Trichterlinge (C. rivulosa/dealbata) achten — nicht nur auf C. phyllophila.$l1$]::text[],$l1$Nelkenschwindling ledergelb-beige mit Buckel und weit stehenden, nicht herablaufenden Lamellen; weiße Trichterlinge reinweiß-bereift mit gedrängten, (schwach) herablaufenden Lamellen.$l1$,$l1$Nelkenschwindling angenehm würzig (Nelke/Bittermandel); der Trichterling muffig-süßlich/parfümiert — Geruch allein ist nicht beweisend.$l1$,$l1$Nelkenschwindling auf Wiesen, Weiden und Rasen (oft in Hexenringen). Clitocybe phyllophila steht vorwiegend in der Laub-/Nadelstreu von Wäldern, Parks und Gärten; die eigentlich gefährlichen WEISSEN WIESEN-Trichterlinge (C. rivulosa/dealbata) teilen dagegen den Rasen-Standort des Nelkenschwindlings.$l1$,$l1$Nelkenschwindling weiß, Bleiweißer Trichterling ebenfalls weiß/creme — Sporenfarbe trennt hier NICHT. Daher Lamellenstellung (weit/nicht herablaufend) und Stielzähigkeit prüfen.$l1$,$l1$Auf Wiese/Rasen nur Pilze mit zäh-biegsamem, nicht brechendem Stiel und weit stehenden, NICHT herablaufenden Lamellen nehmen — jeder weiße Trichterling mit herablaufenden Lamellen (egal ob Wald- oder Wiesenart) bleibt konsequent stehen.$l1$,$l1$pilzkurse.com (Schweiz), pilzbuch-pilzwelten.de, 123pilze, DGfM$l1$),
($l1$amanita_rubescens$l1$,$l1$fliegenpilz-roetlich$l1$,$l1$hoch$l1$,array[$l1$Perlpilz (essbar) rötet bei Verletzung, Druck und Madenfrass deutlich fleisch- bis weinrot/rosa — der braune Königsfliegenpilz (Amanita regalis) tut das NIE.$l1$,$l1$Königsfliegenpilz: weisses Fleisch, aber direkt unter der Huthaut eine charakteristische gelbe bis gelbbraune Zone (im Längs-/Querschnitt sichtbar) — beim Perlpilz fehlt diese gelbe Schicht.$l1$,$l1$Hutfarbe Königsfliegenpilz: leder- bis dunkel-graubraun mit gelblichen bis grauweissen, abwischbaren Velumflocken; Perlpilz: rötlich-braun bis fleischbräunlich mit grauen bis rötlich überhauchten Hautresten.$l1$,$l1$Königsfliegenpilz wächst als Fichten-Symbiont fast nur im sauren Nadelwald (eher Bergland/höhere Lagen) — Perlpilz bevorzugt Laub- und Mischwald, auch tieferlagig und breit verbreitet.$l1$,$l1$Königsfliegenpilz enthält Ibotensäure/Muscimol wie der rote Fliegenpilz (Pantherina-Syndrom: Verwirrung, Halluzinationen, Krämpfe, in grösseren Mengen Kreislaufversagen/Atemlähmung) — kein Speisepilz, auch nicht gekocht.$l1$]::text[],$l1$Königsfliegenpilz hat einen leder- bis dunkel-graubraunen Hut mit gelblich-grauen Velumflocken und eine gelbe bis gelbbraune Zone unter der Huthaut; der Perlpilz rötet an Frass- und Druckstellen rosa bis weinrot und zeigt diese gelbe Subkutiszone nicht.$l1$,$l1$Beide riechen unauffällig pilzig — der Geruch hilft hier NICHT zur Unterscheidung, daher sind die Rötung und die gelbe Schicht unter der Huthaut die entscheidenden Merkmale.$l1$,$l1$Königsfliegenpilz nur im sauren Nadelwald als Fichten-Symbiont (eher Bergland); Perlpilz in Laub-, Nadel- und Mischwald breit verbreitet, auch in tieferen Lagen.$l1$,$l1$Beides Weisssporer — das Sporenpulver trennt die beiden nicht; entscheidend sind Rötung und gelbe Subkutiszone unter der Huthaut.$l1$,$l1$Bei braunhütigen Wulstlingen IMMER das Fleisch anschneiden und 10-15 Min beobachten: rötet es rosa/weinrot = Perlpilz; bleibt es weiss mit gelber Schicht direkt unter der Huthaut = giftiger Königsfliegenpilz, stehen lassen. Im Zweifel bei lamelligen Wulstlingen generell verzichten.$l1$,$l1$DGfM (Pilz des Jahres 2000), 123pilze (Königsfliegenpilz/Brauner Fliegenpilz), Wikipedia Perlpilz, Stadt Wien Konsumentenschutz$l1$),
($l1$laetiporus_sulphureus$l1$,$l1$hapalopilus_nidulans$l1$,$l1$hoch$l1$,array[$l1$Zimtfarbener Weichporling (giftig): KOH/Kalilauge auf Poren oder Fleisch → sofort kräftig violett/lila (auch an Trockenmaterial). Schwefelporling: keine violette Reaktion. Das ist das sicherste Trennmerkmal.$l1$,$l1$Farbe Schwefelporling: jung leuchtend schwefelgelb bis orange. Zimtfarbener Weichporling: höchstens jung stumpf ocker-/ledergelb, rasch zimt- bis rosa-/rotbraun — nie das leuchtende Schwefelgelb-Orange des Schwefelporlings.$l1$,$l1$Zimtfarbener Weichporling ist durch und durch gleichfarbig zimt-/rosabraun (auch Trama) und meist klein (Konsole 3-12 cm, max. ~18 cm); junger Schwefelporling ist innen weisslich-gelb und wird deutlich grösser.$l1$,$l1$Wuchsort Zimtfarbener Weichporling: meist totes Laubholz, gern Eiche und Hasel; Schwefelporling oft an (auch lebenden) Laub- und Obstbäumen (Eiche, Weide, Robinie, Pflaume, Walnuss).$l1$,$l1$Gift: Polyporsäure → nach ~12 h Latenz zentralnervöse Störungen, Sehstörungen, Erbrechen, Nieren-/Leberschäden, violetter Urin — der milde Geschmack warnt NICHT, möglicherweise tödlich.$l1$]::text[],$l1$Schwefelporling ist jung leuchtend schwefelgelb-orange und innen hell; der Zimtfarbene Weichporling ist durchgehend matt ocker-, zimt- bis rosabraun gefärbt und deutlich kleiner (max. ~18 cm).$l1$,$l1$Geruch ist bei beiden schwach und unzuverlässig; der milde Geschmack des Giftpilzes warnt nicht — daher NIE auf Geruch/Geschmack verlassen, sondern KOH-Test machen.$l1$,$l1$Zimtfarbener Weichporling meist auf totem Laubholz (Eiche, Hasel); Schwefelporling häufig als Konsolenbüschel an (auch lebenden) Laub- und Obstbäumen (Eiche, Weide, Robinie, Pflaume).$l1$,$l1$Sporenpulver bei beiden Porlingen weisslich und ohne Sammelpraxis kaum prüfbar — daher KOH-Test statt Sporenpulver verwenden.$l1$,$l1$Braune/ocker Porlinge nie sammeln, ohne mit Kalilauge (KOH) zu testen: violett/lila = giftiger Zimtfarbener Weichporling, stehen lassen. Nur jung leuchtend schwefelgelb-orange wachsende Schwefelporlinge an Laubholz, gegart und nur der weiche Aussensaum, gelten als essbar.$l1$,$l1$Wikipedia Zimtfarbener Weichporling, Stadt Wien Konsumentenschutz, fungiversum.de, pilzbuch-pilzwelten.de (Schwefelporling)$l1$),
($l1$kuehneromyces_mutabilis$l1$,$l1$hypholoma_fasciculare$l1$,$l1$mittel$l1$,array[$l1$Stockschwämmchen: Geschmack mild-nussig; Grünblättriger Schwefelkopf: deutlich und anhaltend BITTER$l1$,$l1$Stockschwämmchen-Lamellen jung hell, dann zimt- bis rostbraun; Schwefelkopf-Lamellen schwefelgelb, dann grünlich bis grünschwärzlich$l1$,$l1$Stockschwämmchen hat häutigen Ring + darunter dunkle, abstehende Schüppchen am Stiel; Schwefelkopf hat höchstens eine flüchtige Ringzone, Stiel kahl gelb-rostbraun$l1$,$l1$Stockschwämmchen-Stiel unterhalb des Rings braun-schuppig genattert; Schwefelkopf-Stiel oben schwefelgelb, nach unten rostbraun, glatt$l1$,$l1$WICHTIGER als der Schwefelkopf: der TÖDLICHE Gifthäubling (Galerina marginata) wächst ebenfalls büschelig an Totholz, sieht dem Stockschwämmchen sehr ähnlich und ist NICHT bitter - Stockschwämmchen nur ernten, wenn man jeden Fruchtkörper am braun-schuppigen Stiel sicher erkennt$l1$]::text[],$l1$Schwefelkopf-Lamellen tragen einen grünlich-schwefelgelben Ton, der dem braunlamelligen Stockschwämmchen fehlt; der braun-schuppig genatterte Stiel unter dem häutigen Ring ist das wichtigste Stockschwämmchen-Merkmal.$l1$,$l1$Stockschwämmchen riecht angenehm pilzig; der Schwefelkopf ist intensiv bitter. ACHTUNG: Eine Geschmacksprobe trennt NUR den Schwefelkopf ab - der tödliche Gifthäubling ist nicht bitter, eine Kostprobe schützt also NICHT vor ihm.$l1$,$l1$Beide wachsen büschelig an Totholz/Stümpfen von Laub- und Nadelholz, sodass das Habitat NICHT zur Unterscheidung taugt.$l1$,$l1$Stockschwämmchen: braunes Sporenpulver (zimt-/rostbraun); Grünblättriger Schwefelkopf: dunkel violett-/purpurbraunes Sporenpulver. Beide sind dunkelsporig - das Sporenpulver trennt sie nur grob, daher zwingend Stiel und Lamellenfarbe prüfen.$l1$,$l1$Niemals nur auf den bitteren Geschmack vertrauen: Das schützt allein vor dem Schwefelkopf, NICHT vor dem tödlichen, mild schmeckenden Gifthäubling. Stockschwämmchen ausschließlich ernten, wenn JEDER Fruchtkörper den häutigen Ring UND darunter den braun-schuppig genatterten Stiel zeigt UND kein Grünton an den Lamellen sichtbar ist - im Zweifel stehen lassen.$l1$,$l1$123pilze, GiftnotrufZentrale (GIZ Bonn), DGfM, AWL.ch, Pilzforum.eu$l1$),
($l1$hallimasch$l1$,$l1$hypholoma_fasciculare$l1$,$l1$mittel$l1$,array[$l1$Hallimasch: Lamellen weisslich bis hell fleischbräunlich, im Alter hell-rostbraun; Schwefelkopf: Lamellen schwefelgelb-grünlich bis grünschwärzlich$l1$,$l1$Hallimasch: deutlicher weisslicher, flockig-watteiger Ring am Stiel; Schwefelkopf: nur flüchtige Ringzone, kein echter Ring$l1$,$l1$Hallimasch: Hut mit feinen dunklen, meist abwischbaren Schüppchen; Schwefelkopf: Hut glatt, schwefel- bis ockergelb$l1$,$l1$Hallimasch: roh giftig, aber gut durchgegart essbar und mild (Kochwasser wegschütten); Schwefelkopf: roh wie gegart bitter und giftig$l1$]::text[],$l1$Der schwefelgelb-grünliche Lamellenton des Schwefelkopfs unterscheidet ihn klar vom hell-fleischfarben lamelligen, fein schuppig-behuteten Hallimasch mit echtem weisslichem Ring.$l1$,$l1$Geschmacksprobe trennt nur Schwefelkopf ab: Hallimasch mild, Schwefelkopf intensiv bitter (Kostprobe nur kauen, nie schlucken).$l1$,$l1$Beide büschelig an Holz/Stümpfen; Habitat trennt sie nicht, daher zwingend Lamellenfarbe, Ring und Sporenpulverfarbe prüfen.$l1$,$l1$Hallimasch: WEISSES Sporenpulver; Grünblättriger Schwefelkopf: dunkel violett-/purpurbraunes Sporenpulver - eindeutiges, sicheres Trennmerkmal.$l1$,$l1$Hallimasch hat einen echten weisslichen Ring und WEISSES Sporenpulver - fehlt der echte Ring oder ist das Sporenpulver dunkel violettbraun und der Geschmack bitter, ist es der Schwefelkopf. Hallimasch immer gut durchgaren, Kochwasser wegschütten.$l1$,$l1$123pilze, GiftnotrufZentrale (GIZ Bonn), DGfM, Stadt Wien Konsumentenschutz, AWL.ch$l1$),
($l1$calocybe_gambosa$l1$,$l1$inocybe_rimosa$l1$,$l1$hoch$l1$,array[$l1$Maipilz riecht stark mehlig-gurkig; Kegeliger Risspilz riecht spermatisch/erdig-unangenehm$l1$,$l1$Maipilz-Hut weisslich bis cremefarben, glatt, am Rand eingerollt; Risspilz-Hut ocker-/strohbraun, kegelig-gebuckelt und radial AUFGERISSEN (rissige Hutoberfläche)$l1$,$l1$Maipilz-Lamellen weiss bis creme, dicht; Risspilz-Lamellen jung blass, bald tonig-graubraun$l1$,$l1$Risspilze enthalten Muscarin (Schweissausbruch, Speichelfluss, Sehstörung 15-120 Min) - der nah verwandte Ziegelrote Risspilz (Inocybe erubescens) am selben Standort hat sogar Todesfälle verursacht; Maipilz ungiftig$l1$,$l1$Beide erscheinen im Frühling (April/Mai) am selben Standort - Verwechslung gerade deshalb gefährlich$l1$]::text[],$l1$Der radial eingerissene, kegelig-gebuckelte ocker-braune Risspilz-Hut steht im klaren Kontrast zum glatten, weisslichen, gewölbten Maipilz-Hut.$l1$,$l1$Maipilz: ausgeprägt mehlig-gurkig (Frischmehl); Risspilz: spermatisch/säuerlich-erdig - der Mehlgeruch ist das wichtigste Bestätigungsmerkmal für den Maipilz.$l1$,$l1$Beide an Wiesen, Hecken, Weg- und Waldrändern im Frühjahr; Habitat und Jahreszeit überschneiden sich, deshalb nur über Geruch und Sporenfarbe trennbar.$l1$,$l1$Maipilz: WEISSES Sporenpulver; Kegeliger Risspilz: tabak-/graubraunes Sporenpulver - eindeutiges Trennmerkmal.$l1$,$l1$Mai-Pilze nur ernten, wenn sie klar mehlig-gurkig riechen UND weisses Sporenpulver geben; jeder kegelige, radial aufgerissene Hut mit braunem Sporenstaub und unangenehmem Geruch ist ein Risspilz - sofort verwerfen.$l1$,$l1$123pilze, VAPKO, DGfM, GiftnotrufZentrale, Pilzmuseum.at$l1$),
($l1$marasmius_oreades$l1$,$l1$inocybe_rimosa$l1$,$l1$hoch$l1$,array[$l1$Nelkenschwindling: Lamellen weisslich-creme, dick, entfernt stehend; Risspilz: Lamellen bald tonig-graubraun, dichter$l1$,$l1$Nelkenschwindling: Hut hellbraun-ledergelb, glatt mit stumpfem Buckel, zäh-biegsamer Stiel (lässt sich biegen ohne zu brechen); Risspilz: Hut radial AUFGERISSEN, kegelig, Stiel brüchig$l1$,$l1$Nelkenschwindling riecht angenehm nach Bittermandel; Risspilz riecht spermatisch-erdig$l1$,$l1$Risspilze enthalten Muscarin - in Menge gefährlich; Nelkenschwindling ist essbar (durchgaren)$l1$]::text[],$l1$Der zähe, biegsame Stiel und der glatte ledergelbe Hut des Nelkenschwindlings unterscheiden ihn vom rissig-kegeligen, brüchigen Risspilz.$l1$,$l1$Nelkenschwindling: angenehm nach Bittermandel; Risspilz: spermatisch-unangenehm.$l1$,$l1$Beide auf Wiesen und in kurzem Gras; der Nelkenschwindling wächst oft in Hexenringen, aber das Habitat trennt sie nicht zuverlässig.$l1$,$l1$Nelkenschwindling: WEISSES Sporenpulver; Kegeliger Risspilz: tabak-/graubraunes Sporenpulver - sicheres Trennmerkmal.$l1$,$l1$Auf der Wiese nur Pilze mit weisslichen Lamellen, weissem Sporenpulver und biegsam-zähem Stiel nehmen; jeder rissige, braunsporige, spermatisch riechende Hut ist ein Giftrisspilz - sofort verwerfen.$l1$,$l1$123pilze, VAPKO, DGfM, Pilzforum.eu, Stadt Wien Konsumentenschutz$l1$),
($l1$marasmius_oreades$l1$,$l1$inocybe_geophylla$l1$,$l1$hoch$l1$,array[$l1$Nelkenschwindling: Lamellen weisslich-creme, dick und entfernt; Erdblättriger Risspilz: Lamellen jung weisslich, bald tonig-/tabakbraun$l1$,$l1$Nelkenschwindling: Hut ledergelb-hellbraun mit stumpfem Buckel; weisse Form des Risspilzes: rein weiss bis cremefarben, seidig-faserig mit spitzem Buckel$l1$,$l1$Nelkenschwindling: Stiel zäh-biegsam (lässt sich um den Finger biegen); Risspilz: Stiel brüchig, dünn$l1$,$l1$Erdblättriger Risspilz enthält viel Muscarin (Schweiss, Speichel, Tränen 15-30 Min nach Verzehr); Nelkenschwindling essbar$l1$]::text[],$l1$Die rein weiss-seidige, spitz gebuckelte Hutoberfläche des Erdblättrigen Risspilzes unterscheidet sich vom ledergelb-bräunlichen, stumpf gebuckelten Nelkenschwindling.$l1$,$l1$Nelkenschwindling: nach Bittermandel; Erdblättriger Risspilz: spermatisch-erdig.$l1$,$l1$Beide an Wiesen-, Weg- und Waldrändern in kurzem Gras; Habitat trennt nicht, daher Lamellenfarbe, Geruch und Stielkonsistenz prüfen.$l1$,$l1$Nelkenschwindling: WEISSES Sporenpulver; Erdblättriger Risspilz: tabak-/ockerbraunes Sporenpulver - sicheres Trennmerkmal.$l1$,$l1$Kleine weisse/hellbraune Wiesenpilze nur essen, wenn das Sporenpulver WEISS bleibt; jeder seidig-weisse Hut mit braunem Sporenstaub und spermatischem Geruch ist ein Risspilz - verwerfen.$l1$,$l1$123pilze, VAPKO, DGfM, GiftnotrufZentrale$l1$),
($l1$parasol$l1$,$l1$lepiota_brunneoincarnata$l1$,$l1$sehr_hoch_lebensgefahr$l1$,array[$l1$Parasol ist gross: Hut 10-30 cm; Fleischrötlicher Schirmling klein: Hut nur 2-5 cm - GRÖSSE ist das erste Warnsignal$l1$,$l1$Parasol hat einen DOPPELTEN, frei verschiebbaren Ring am Stiel; der Giftschirmling hat nur eine flüchtige, faserige, NICHT verschiebbare Ringzone$l1$,$l1$Parasol-Stiel deutlich genattert (schlangenhautartig gebändert); Giftschirmling-Stiel mit fleischbräunlich-faserigen Schuppengürteln, ohne Natterung$l1$,$l1$Parasol-Hut mit grossen, groben braunen Schuppen auf hellem Grund + Buckel; Giftschirmling-Hut fein fleischbraun-rosa schuppig, klein$l1$,$l1$Fleischrötlicher Schirmling enthält Amatoxine (wie Knollenblätterpilz) - tödlich, schon eine kleine Menge schädigt die Leber irreversibel$l1$]::text[],$l1$Der Parasol ist gross mit deutlich genattertem Stiel und doppeltem verschiebbarem Ring; der tödliche Schirmling bleibt klein (unter 5 cm) mit fleischrosa-brauner, fein schuppiger Hutoberfläche und ungenattertem Stiel.$l1$,$l1$Parasol riecht mild-nussig; der Giftschirmling süsslich-obstartig - Geruch ist KEIN sicheres Trennmerkmal, niemals darauf verlassen.$l1$,$l1$Parasol an Waldrändern/Wiesen; der Giftschirmling an warmen, sandig-grasigen Plätzen, Parks und Wegrändern - Überschneidung möglich.$l1$,$l1$Beide haben WEISSES Sporenpulver - das Sporenpulver trennt sie NICHT, daher zwingend Grösse, Stielnatterung und doppelten verschiebbaren Ring prüfen.$l1$,$l1$Schirmlinge nur als Parasol akzeptieren, wenn der Hut deutlich über 10 cm misst UND der Stiel genattert ist UND der Ring doppelt und verschiebbar ist - kleine Schirmlinge unter 8-10 cm grundsätzlich NIE essen.$l1$,$l1$123pilze, VAPKO, DGfM, GiftnotrufZentrale, Wikipedia (Lepiota brunneoincarnata)$l1$),
($l1$chlorophyllum_rhacodes$l1$,$l1$lepiota_brunneoincarnata$l1$,$l1$sehr_hoch_lebensgefahr$l1$,array[$l1$Safran-Riesenschirmling ist gross: Hut 8-20 cm; Fleischrötlicher Schirmling klein: nur 2-5 cm$l1$,$l1$Safran-Riesenschirmling: Fleisch verfärbt sich beim Anschneiden/Reiben SAFRAN-/orangerot; Giftschirmling verfärbt sich nicht safranrot$l1$,$l1$Safran-Riesenschirmling: dicker verschiebbarer Ring, Stiel glatt (NICHT genattert); Giftschirmling: nur flüchtige faserige Ringzone, fleischbraun beschuppter Stiel$l1$,$l1$Fleischrötlicher Schirmling enthält tödliche Amatoxine; Safran-Riesenschirmling ist essbar (kann roh/ungenügend gegart Magen-Darm-Beschwerden machen)$l1$]::text[],$l1$Das beim Schnitt safran-/orangerot anlaufende Fleisch ist typisch für den essbaren Safran-Riesenschirmling und fehlt dem kleinen, fleischrosa-braunen Giftschirmling.$l1$,$l1$Safran-Riesenschirmling mild-pilzig; Giftschirmling süsslich-obstartig - Geruch ist kein sicheres Kriterium.$l1$,$l1$Safran-Riesenschirmling an nährstoffreichen Stellen, Komposten, Nadelwald, Gärten; Giftschirmling an sandig-grasigen, parkartigen Plätzen - Überschneidung möglich.$l1$,$l1$Beide mit weisslichem Sporenpulver - kein Trennmerkmal, deshalb Grösse, Safranreaktion des Fleischs und Ring prüfen.$l1$,$l1$Riesenschirmling nur ernten, wenn der Hut gross ist (über 8 cm) UND das Fleisch beim Reiben/Schneiden safran-orangerot anläuft - kleine Schirmlinge unter 8 cm grundsätzlich stehen lassen.$l1$,$l1$123pilze, VAPKO, DGfM, Wikipedia (Gemeiner Safranschirmling)$l1$),
($l1$macrolepiota_mastoidea$l1$,$l1$lepiota_brunneoincarnata$l1$,$l1$sehr_hoch_lebensgefahr$l1$,array[$l1$Zitzen-Riesenschirmling: Hut 6-12 cm mit markanter spitzer Zitze in der Mitte; Fleischrötlicher Schirmling: nur 2-5 cm$l1$,$l1$Zitzen-Riesenschirmling: verschiebbarer Ring; Giftschirmling: flüchtige, nicht verschiebbare faserige Ringzone$l1$,$l1$Zitzen-Riesenschirmling: Stiel höchstens fein/zart genattert (schwächer als beim Parasol); Giftschirmling: Stiel ungenattert, mit fleischbraunen Schuppengürteln$l1$,$l1$Zitzen-Riesenschirmling-Hut fein hellbraun beschuppt auf weisslichem Grund; Giftschirmling-Hut fleischrosa-braun, in konzentrische Schuppen aufgelöst$l1$,$l1$Fleischrötlicher Schirmling enthält tödliche Amatoxine; der Zitzen-Riesenschirmling ist essbar - weil der Grössenunterschied hier kleiner ist, ist diese Verwechslung besonders heikel$l1$]::text[],$l1$Der Zitzen-Riesenschirmling zeigt eine ausgeprägte spitze Mittelzitze und verschiebbaren Ring; der tödliche Schirmling bleibt deutlich kleiner mit fleischrosa-brauner Erscheinung und ungenattertem, schuppig gegürteltem Stiel.$l1$,$l1$Beide unauffällig bis leicht süsslich - Geruch trennt sie NICHT, niemals darauf verlassen.$l1$,$l1$Beide an grasigen Waldrändern, Wiesen und Parks - starke Überschneidung, daher nur über Grösse, spitze Zitze, Stielmerkmale und verschiebbaren Ring sicher trennbar.$l1$,$l1$Beide mit weissem Sporenpulver - kein Trennmerkmal.$l1$,$l1$Da der Grössenunterschied hier kleiner ist, gilt erst recht: nur Schirmlinge mit klar verschiebbarem Ring, spitzer Mittelzitze und Hut deutlich über 8 cm akzeptieren; im Zweifel jeden kleinen Schirmling stehen lassen.$l1$,$l1$123pilze, VAPKO, DGfM, GiftnotrufZentrale, Wikipedia (Zitzen-Riesenschirmling)$l1$),
($l1$eierschwamm$l1$,$l1$omphalotus_olearius$l1$,$l1$hoch$l1$,array[$l1$Oelbaumtrichterling hat echte, scharfkantige, gedraengte Lamellen; der Pfifferling hat KEINE echten Lamellen, sondern nur stumpfe, gabelige, dicke Leisten (verdickte Aderfalten), die weit am Stiel herablaufen$l1$,$l1$Oelbaumtrichterling waechst bueschelig direkt an/auf Holz und Wurzeln (Eiche, Olive, Edelkastanie, Stuempfe); echter Pfifferling waechst einzeln bis verstreut aus dem Waldboden (Mykorrhiza), nie bueschelig an Holz$l1$,$l1$Farbe Oelbaumtrichterling kraeftig orange bis orangerot/braunorange; Pfifferling blass dotter- bis eigelb, gleichmaessig$l1$,$l1$Lamellen des frischen Oelbaumtrichterlings leuchten im Dunkeln schwach gruenlich (Biolumineszenz) - der Pfifferling nie$l1$,$l1$Pfifferling-Fleisch ist faserig-zaeh, durchgehend blassgelb und reisst faserig; Oelbaumtrichterling-Fleisch weicher, gegen die Basis orange-braun$l1$]::text[],$l1$Oelbaumtrichterling kraeftig orange mit echten, duennen, gedraengten Lamellen und trichterig vertieftem Hut, bueschelig an Holz; Pfifferling blassgelb mit dicklichen, gabeligen, herablaufenden Leisten, einzeln am Boden.$l1$,$l1$Pfifferling riecht angenehm fruchtig nach Aprikose; der Oelbaumtrichterling riecht unauffaellig bis leicht unangenehm, ohne Aprikosennote.$l1$,$l1$Oelbaumtrichterling bueschelig an Laubholz/Stuempfen/Wurzeln (waermeliebend, in der Schweiz selten und nur in milden Lagen); Pfifferling einzeln aus dem Boden im Nadel- und Laubwald, in der Schweiz haeufig.$l1$,$l1$Beide weisslich bis blass cremefarben - das Sporenpulver trennt sie NICHT. Entscheidend sind echte Lamellen vs. dicke Leisten und Wuchsform (Holz vs. Boden).$l1$,$l1$Echte, scharfkantige Lamellen + buescheliges Wachstum direkt an Holz = NIEMALS ein Pfifferling, egal wie gelb. Ein Pfifferling hat nur dicke, gabelige, herablaufende Leisten und steht einzeln aus dem Boden.$l1$,$l1$123pilze (Oelbaumtrichterling), AWL.ch (Pfifferling), Wikipedia (Dunkler Oelbaumtrichterling), DGfM$l1$),
($l1$marasmius_oreades$l1$,$l1$lepiota_helveola$l1$,$l1$sehr_hoch_lebensgefahr$l1$,array[$l1$Lepiota helveola ist TOEDLICH giftig (Amatoxine -> Leberversagen); der Nelkenschwindling ist ein guter Speisepilz - die Verwechslung kann toedlich enden$l1$,$l1$Nelkenschwindling hat einen auffallend zaehen, biegsam-elastischen, vollen Stiel (laesst sich verdrehen ohne zu brechen); kleine Giftschirmlinge haben einen zerbrechlichen, leicht brechenden Stiel$l1$,$l1$Lepiota helveola besitzt einen (oft vergaenglichen) haeutigen Ring am Stiel; der Nelkenschwindling hat NIE einen Ring$l1$,$l1$Nelkenschwindling hat dicke, weit stehende, am Stiel ausgebuchtet angewachsene, cremefarbene Lamellen; Lepiota helveola dicht stehende, freie, weisse Lamellen$l1$,$l1$Lepiota helveola: feinschuppiger fleischrosa bis braunroetlicher Hut mit dunklerem Zentrum; Nelkenschwindling: glatter ocker- bis semmelfarbener Hut mit stumpfem Buckel$l1$]::text[],$l1$Nelkenschwindling glatter ockerfarbener Buckelhut, ringloser zaeher Stiel, dicke weit stehende Lamellen; Lepiota helveola feinschuppiger fleischroetlicher Hut mit Stielring und dicht stehenden freien Lamellen.$l1$,$l1$Nelkenschwindling riecht angenehm nach Blausaeure/Bittermandel bis suesslich (HCN + Benzaldehyd, von ca. einem Viertel der Menschen nicht wahrnehmbar); kleine Giftschirmlinge riechen unauffaellig bis leicht unangenehm - der Geruch ist KEIN sicheres Trennmerkmal.$l1$,$l1$Beide auf Wiesen, Rasen, Weiden und in Parks - identischer Lebensraum, genau das macht die Verwechslung so gefaehrlich.$l1$,$l1$Nelkenschwindling weisses Sporenpulver, Lepiota helveola ebenfalls weiss - kein Trennmerkmal; auf Ring, freie Lamellen und bruechigen Stiel achten.$l1$,$l1$Kleine Schirmlinge (Lepiota) mit Hut unter ca. 8 cm NIE essen - mehrere Arten sind toedlich. Auf der Wiese keinen kleinen, geringten, bruechigen Pilz sammeln; im Zweifel komplett stehen lassen.$l1$,$l1$123pilze (Fleischroetlicher Schirmling), Wikipedia Lepiota helveola, DGfM, GiftnotrufZentrale (Notruf Schweiz 145)$l1$),
($l1$marasmius_oreades$l1$,$l1$lepiota_cristata$l1$,$l1$mittel$l1$,array[$l1$Lepiota cristata ist giftig (Magen-Darm-Stoerungen, in der Gattung gilt jeder kleine Schirmling als amatoxin-verdaechtig); der Nelkenschwindling ist essbar$l1$,$l1$Lepiota cristata riecht unangenehm scharf nach Leuchtgas/verbranntem Gummi; der Nelkenschwindling riecht angenehm nach Bittermandel/Blausaeure bis suesslich$l1$,$l1$Lepiota cristata hat einen (vergaenglichen) Ring und einen bruechigen Stiel; der Nelkenschwindling hat KEINEN Ring und einen zaehen, biegsamen Stiel$l1$,$l1$Lepiota cristata: weisslicher Hut mit rotbraunen, konzentrisch gestellten Schuppen und dunklem Scheibchen in der Mitte; Nelkenschwindling: glatter ocker- bis semmelfarbener Buckelhut ohne Schuppen$l1$,$l1$Lepiota cristata mit dicht stehenden, freien, weissen Lamellen; Nelkenschwindling mit dicken, weit stehenden, ausgebuchtet angewachsenen Lamellen$l1$]::text[],$l1$Lepiota cristata weisslicher Hut mit rotbraunem konzentrischem Schuppenkranz, dunklem Zentrum und Stielring; Nelkenschwindling glatter ockerfarbener Buckelhut ohne Schuppen und ohne Ring.$l1$,$l1$Lepiota cristata stechend unangenehm nach Leuchtgas/verbranntem Gummi; Nelkenschwindling angenehm nach Bittermandel/Blausaeure - der Leuchtgasgeruch ist ein klares Warnsignal.$l1$,$l1$Beide an grasigen Stellen, Wegraendern, in Parks und auf Wiesen - derselbe Lebensraum beguenstigt die Verwechslung.$l1$,$l1$Beide weisses (bei Lepiota cristata gelegentlich minimal cremefarbenes) Sporenpulver - kein verlaessliches Trennmerkmal.$l1$,$l1$Kleine Schirmlinge mit Ring auf Wiesen grundsaetzlich stehen lassen; der ringlose, zaehe, verdrehbare Stiel ist das einzige verlaessliche Merkmal des Nelkenschwindlings - fehlt er, nicht sammeln.$l1$,$l1$123pilze (Stink-Schirmling), pilzbuch-pilzwelten, Wikipedia Stink-Schirmling, DGfM$l1$),
($l1$lepista_nuda$l1$,$l1$mycena_pura$l1$,$l1$mittel$l1$,array[$l1$Mycena pura ist giftig (enthaelt Muscarin, frueher faelschlich als essbar gefuehrt); der Violette Roetelritterling ist nur DURCHGEGART essbar$l1$,$l1$Mycena pura riecht intensiv und durchdringend nach Rettich; Lepista nuda riecht angenehm wuerzig-parfuemiert, nie nach Rettich$l1$,$l1$Mycena pura ist klein und duennfleischig (Hut nur bis ca. 4 cm, glasig-helmfoermig, gerieft); Lepista nuda kraeftig fleischig (Hut 5-15 cm, nicht gerieft)$l1$,$l1$Mycena pura mit duennem, hohlem, zerbrechlichem Stiel; Lepista nuda mit festem, faserig-vollem, oft violettem Stiel$l1$,$l1$Lepista nuda durchgehend kraeftig violett bis graulila (Hut, Lamellen, Stiel); Mycena pura nur blass lila/rosa und rasch ausbleichend$l1$]::text[],$l1$Lepista nuda gross, fleischig, durchgehend kraeftig violett mit ungerieftem Hut; Mycena pura klein, glasig-gerieft, blasslila und schnell ausbleichend.$l1$,$l1$Mycena pura stark und durchdringend nach Rettich; Lepista nuda angenehm wuerzig-parfuemiert - der Rettichgeruch ist das wichtigste Warnsignal.$l1$,$l1$Beide im Laub- und Nadelwald auf der Streu; Lepista nuda oft gesellig oder in Hexenringen im Falllaub, Mycena pura einzeln bis gesellig auf Streu und Nadeln.$l1$,$l1$Lepista nuda rosa- bis blasslila Sporenpulver; Mycena pura weisses Sporenpulver - die Sporenpulverfarbe trennt die beiden eindeutig.$l1$,$l1$Jeder kleine, duennfleischige, gerieft-glasige Lilapilz mit starkem Rettichgeruch ist verdaechtig - Rettichgeruch + weisses Sporenpulver schliessen den essbaren Roetelritterling sicher aus.$l1$,$l1$123pilze, Wikipedia (Gemeiner Rettich-Helmling / Lepista nuda), pilzbuch-pilzwelten, DGfM$l1$),
($l1$hallimasch$l1$,$l1$pholiota_squarrosa$l1$,$l1$mittel$l1$,array[$l1$Sparriger Schüppling: trockene, abstehende (sparrige), grobe braune Schuppen auf Hut UND Stiel; Hallimasch hat nur feine, vergängliche, anliegende Flöckchen auf dem Hut$l1$,$l1$Sporenpulver: Schüppling rostbraun → Lamellen verfärben braun; Hallimasch weiss → Lamellen bleiben hell/cremeweiss$l1$,$l1$Hallimasch hat einen dicken, häutigen weissen Ring; der Ring des Schüpplings ist sparrig-faserig/wollig und undeutlich$l1$,$l1$Sparriger Schüppling riecht aufdringlich würzig-rettich-/lauchartig, Hallimasch eher pilzig-mild$l1$,$l1$Geschmack des Schüpplings bitter/unangenehm (Kostprobe ausspucken, nie roh schlucken)$l1$]::text[],$l1$Grobe abstehende sparrige Schuppen auf Hut und Stiel beim Schüppling statt der feinen, abwischbaren, vergänglichen Flöckchen des Hallimasch.$l1$,$l1$Sparriger Schüppling riecht aufdringlich rettich-/lauchartig, Hallimasch mild pilzig.$l1$,$l1$Beide büschelig an Laub-/Nadelholz und Stümpfen, gleiche Saison Herbst — Standort taugt NICHT zur Unterscheidung.$l1$,$l1$Sparriger Schüppling rostbraunes Sporenpulver, Hallimasch weisses — Lamellenfarbe im Alter beachten (Sporenabwurf machen).$l1$,$l1$Sporenpulverfarbe entscheidet: rostbraun = niemals Hallimasch, Finger weg. Büschelpilze an Holz immer einzeln durchprüfen, nie pauschal als Hallimasch ernten. Hallimasch zudem nur gut durchgegart geniessbar.$l1$,$l1$123pilze, AWL.ch, Wikipedia (Sparriger Schüppling), Toxinfo$l1$),
($l1$kuehneromyces_mutabilis$l1$,$l1$pholiota_squarrosa$l1$,$l1$mittel$l1$,array[$l1$Sparriger Schüppling hat einen trockenen, sparrig-schuppigen Hut; Stockschwämmchen hat einen glatten bis fein faserigen, hygrophanen Hut mit ausblassendem Rand (zweifarbig)$l1$,$l1$Schüppling deutlich grösser und robuster, oft 5–12 cm Hut; Stockschwämmchen klein, 3–6 cm$l1$,$l1$Stockschwämmchen-Stiel unterhalb des Rings dunkelbraun und fein beschuppt/genattert; Schüppling-Stiel grob sparrig beschuppt$l1$,$l1$Geschmack: Schüppling bitter/unangenehm, Stockschwämmchen mild$l1$,$l1$Beide rostbraunes Sporenpulver — hier kein Unterscheidungsmerkmal$l1$]::text[],$l1$Trockener, grob-sparriger Hut beim Schüppling vs. glatter, hygrophan zweifarbiger Hut mit ausblassendem Rand beim Stockschwämmchen.$l1$,$l1$Schüppling aufdringlich rettichartig, Stockschwämmchen angenehm würzig-mild.$l1$,$l1$Beide büschelig an Holz/Stümpfen — Standort nicht trennend.$l1$,$l1$Beide rostbraun — taugt hier NICHT zur Abgrenzung, daher andere Merkmale zwingend.$l1$,$l1$Vorsicht: Stockschwämmchen ist selbst Anfänger-Tabu wegen des tödlichen Gifthäublings (Galerina marginata). Schüppling, Stockschwämmchen und Gifthäubling wachsen alle büschelig an Holz — diese Gruppe nur mit Expertenwissen und Sporenabwurf ernten.$l1$,$l1$123pilze, CVUA Stuttgart, Wikipedia (Gemeines Stockschwämmchen), Pilzbuch-Pilzwelten$l1$),
($l1$kuehneromyces_mutabilis$l1$,$l1$pholiotina_rugosa$l1$,$l1$sehr_hoch_lebensgefahr$l1$,array[$l1$Pholiotina rugosa (= Conocybe filaris) ist ein kleiner brauner Pilz (LBM) mit dünnem, brüchigem Stiel und einem beweglichen, häutigen Ring — enthält tödliche Amatoxine wie der Grüne Knollenblätterpilz$l1$,$l1$Pholiotina wächst EINZELN bis gesellig auf Erde, Rasen, Wegrändern, Mulch, Holzhäcksel/Komposterde — NICHT büschelig an Stümpfen; Stockschwämmchen wächst dicht büschelig auf morschem Holz/Stümpfen$l1$,$l1$Stockschwämmchen-Stiel unter dem Ring deutlich dunkelbraun und fein schuppig genattert; Pholiotina-Stiel glatt, blass, ohne Natterung$l1$,$l1$Stockschwämmchen-Hut hygrophan, zweifarbig mit ausblassendem Rand; Pholiotina-Hut ockerbraun, runzelig, ohne diese Zweifarbigkeit$l1$,$l1$Pholiotina ist meist viel kleiner und zierlicher als ein typisches Stockschwämmchen$l1$]::text[],$l1$Stockschwämmchen büschelig am Holz mit genattertem dunklem Stiel; Pholiotina einzeln/gesellig auf Erde, glatter blasser Stiel, runzeliger Hut.$l1$,$l1$Stockschwämmchen angenehm würzig; Pholiotina rugosa unauffällig bis leicht ranzig — Geruch ist KEIN sicheres Trennkriterium.$l1$,$l1$Entscheidend, aber NICHT allein verlassen: Stockschwämmchen büschelig an Holz; Pholiotina rugosa auf Boden/Rasen/Mulch/Häcksel. Da Pholiotina auch auf Holzhäcksel fruchten kann, ist Holznähe allein kein Freibrief — immer mehrere Merkmale prüfen.$l1$,$l1$Stockschwämmchen rostbraun; Pholiotina rugosa rostbraun bis zimtbraun — Sporenfarbe trennt NICHT, daher Standort, Stiel-Natterung und Habitus entscheidend.$l1$,$l1$Kleine braune Pilze (LBMs) mit Ring NIE für Stockschwämmchen halten, wenn sie auf Erde/Rasen/Mulch statt büschelig an Holz wachsen — Lebensgefahr durch Amatoxin. Im Notfall Tox Info Suisse 145 anrufen.$l1$,$l1$DGfM, GiftnotrufZentrale, Wikipedia/healing-mushrooms (Pholiotina rugosa / Conocybe filaris), bayareamushrooms.org (Amatoxin)$l1$),
($l1$butyriboletus_appendiculatus$l1$,$l1$roehrling_flockenstielig$l1$,$l1$mittel$l1$,array[$l1$Schönfuß-Röhrling (Caloboletus calopus) schmeckt deutlich BITTER — Kostprobe (Zungenspitze, ausspucken) ist das sichere Trennkriterium; Anhängselröhrling schmeckt mild-nussig$l1$,$l1$Schönfuß hat einen blass lehmgrauen/graubraunen Hut; Anhängselröhrling hat einen warm ocker- bis kastanienbraunen Hut$l1$,$l1$Schönfuß-Stiel mit kräftig rotem Bereich und Netz im unteren Stielteil; Anhängselröhrling-Stiel überwiegend gelb mit feinem gelblichem Netz und nur rötlicher Basis$l1$,$l1$Beide blauen bei Druck/Anschnitt (Poren/Fleisch) — das Blauen allein trennt NICHT; entscheidend sind Bittergeschmack und Stielfarbe$l1$,$l1$Schönfuß bevorzugt sauren, mageren Boden (gern Nadel-/Bergwald); Anhängselröhrling wärmeliebend in Laubwald auf kalkhaltigem Boden$l1$]::text[],$l1$Lehmgrau-graubrauner Hut + roter unterer Stielteil beim Schönfuß vs. ocker-/kastanienbrauner Hut + überwiegend gelber Stiel beim Anhängselröhrling.$l1$,$l1$Beide unauffällig pilzig — Geruch trennt nicht; der Geschmackstest (bitter vs. mild) ist entscheidend.$l1$,$l1$Schönfuß auf saurem, magerem Boden/Nadel-/Bergwald; Anhängselröhrling wärmeliebend im Laubwald auf Kalk.$l1$,$l1$Beide olivbraunes Sporenpulver — kein Unterscheidungsmerkmal.$l1$,$l1$Bei jedem Röhrling mit Stielnetz die Bitter-Kostprobe machen: bitter = wegwerfen. Netz am Stiel + bitterer Geschmack = Schönfuß, ungeniessbar. Der Anhängselröhrling ist zudem geschützt/selten — im Zweifel stehen lassen.$l1$,$l1$123pilze, AWL.ch, Wikipedia (Schönfuß-Röhrling), tintling.com$l1$),
($l1$steinpilz$l1$,$l1$roehrling_flockenstielig$l1$,$l1$mittel$l1$,array[$l1$Schönfuß-Röhrling schmeckt bitter und sein Fleisch BLAUT beim Anschnitt; Steinpilz schmeckt nussig-mild und sein Fleisch bleibt weiss/unverändert (blaut nicht)$l1$,$l1$Schönfuß hat ein deutlich ROTES Netz/roten Bereich am Stiel; Steinpilz hat ein weisses bis hellbräunliches Netz auf hellem Stiel$l1$,$l1$Schönfuß-Poren gelb (auf Druck blauend); Steinpilz-Röhren weiss → gelb → olivgrün, ohne zu blauen$l1$,$l1$Schönfuß-Hut lehmgrau/graubraun matt; Steinpilz-Hut warm hell- bis dunkelbraun, oft speckig glänzend$l1$,$l1$Geschmackskostprobe: Schönfuß bitter, Steinpilz mild — sicheres Trennkriterium$l1$]::text[],$l1$Rotes Stielnetz + blauendes gelbes Porenfeld beim Schönfuß vs. weisses Netz + stabil weisses Fleisch und nicht-blauende Röhren beim Steinpilz.$l1$,$l1$Beide angenehm pilzig; Geschmackstest entscheidet — Schönfuß bitter, Steinpilz mild-nussig.$l1$,$l1$Grosse Überlappung in Misch-/Nadelwald — Standort trennt nicht zuverlässig.$l1$,$l1$Beide olivbraun — kein Unterscheidungsmerkmal.$l1$,$l1$Merksatz: Blaut das Fleisch/Poren oder ist das Stielnetz rot, ist es kein Steinpilz. Beim Steinpilz bleibt Fleisch weiss und Netz hell — jedes Blauen oder rotes Netz = nicht Steinpilz, nicht in den Korb.$l1$,$l1$123pilze, Wikipedia (Schönfuß-Röhrling), SwissFungi/AWL.ch$l1$),
($l1$suillellus_luridus$l1$,$l1$rubroboletus_legaliae$l1$,$l1$hoch$l1$,array[$l1$Le Gals (Rubroboletus legaliae) hat einen blassen, weisslich/grau bis weinrosa-altrosa Hut; Netzstieliger Hexen-Röhrling hat einen ockerbraunen bis ziegelrot-dunkeloliven Hut$l1$,$l1$Le Gals riecht auffällig würzig nach Liebstöckel/Sellerie/Zichorie; Netzstieliger Hexen-Röhrling riecht neutral pilzig$l1$,$l1$Le Gals blaut nur schwach/mässig im Fleisch und NICHT in der Huthaut; Netzstieliger Hexen-Röhrling blaut sofort kräftig dunkelblau (auch Huthaut/Fleisch)$l1$,$l1$Beide haben rote/karminrote Poren und ein Stielnetz — diese Merkmale trennen NICHT; entscheidend sind Hutfarbe, Selleriegeruch und Blau-Intensität$l1$,$l1$Le Gals ist auch gut erhitzt giftig/unverträglich (schwere Magen-Darm-Störungen gemeldet); Netzstieliger Hexen-Röhrling NUR roh giftig, ausreichend durcherhitzt essbar (auch dann nicht mit Alkohol)$l1$]::text[],$l1$Blasser weiss-/graurosa Hut beim Le Gals vs. ocker-/ziegelrot-dunkeloliver Hut beim Netzstieligen Hexen-Röhrling; bei Le Gals KEIN Blauen der Huthaut, beim Hexen-Röhrling starkes Blauen.$l1$,$l1$Le Gals deutlich nach Sellerie/Liebstöckel; Netzstieliger Hexen-Röhrling geruchlich neutral.$l1$,$l1$Le Gals selten, wärmeliebend unter alten Eichen/Buchen auf Kalk; Netzstieliger Hexen-Röhrling häufiger in Laub-/Mischwald auf Kalk — Überlappung möglich, Standort trennt nicht sicher.$l1$,$l1$Beide olivbraunes Sporenpulver — kein Trennmerkmal.$l1$,$l1$Rotporige Röhrlinge nur als erfahrener Sammler nehmen: blasser/rosa Hut + Selleriegeruch + nur schwaches Blauen = Le-Gals-/Satans-Gruppe, giftig. Die sogenannte Bataille-Linie (rote Linie über den Röhren) ist KEIN sicheres Bestimmungsmerkmal — sie fehlt vielen echten Netzhexen und ist überbewertet. Im Zweifel stehen lassen.$l1$,$l1$123pilze (Falscher Satansröhrling), Wikipedia (Rubroboletus legaliae / Suillellus luridus), AWL.ch, VAPKO$l1$),
($l1$butyriboletus_appendiculatus$l1$,$l1$rubroboletus_legaliae$l1$,$l1$hoch$l1$,array[$l1$Le Gals hat ROTE bis orangerote/blutrote Poren; Anhängselröhrling hat GELBE Poren — rote Poren bei Röhrlingen sind ein generelles Warnsignal$l1$,$l1$Le Gals hat einen blassen weiss-/graurosa bis altrosa Hut; Anhängselröhrling einen warm ocker- bis kastanienbraunen Hut$l1$,$l1$Le Gals riecht nach Sellerie/Liebstöckel und ist auch gekocht giftig/unverträglich; Anhängselröhrling riecht mild pilzig und ist mild-essbar$l1$,$l1$Le Gals-Stiel mit rotem Netz auf rötlich-orangem Grund; Anhängselröhrling-Stiel überwiegend gelb mit feinem gelblichem Netz$l1$,$l1$Beide können blauen — das Blauen allein reicht NICHT; entscheidend ist die Porenfarbe (rot vs. gelb) plus Selleriegeruch$l1$]::text[],$l1$Rote Poren + blass-/graurosa Hut beim Le Gals vs. gelbe Poren + ocker-/kastanienbrauner Hut beim Anhängselröhrling.$l1$,$l1$Le Gals nach Sellerie/Liebstöckel; Anhängselröhrling mild pilzig.$l1$,$l1$Beide wärmeliebend im Laubwald (Eiche/Buche) auf Kalk — Standort überlappt, trennt nicht.$l1$,$l1$Beide olivbraun — kein Trennmerkmal.$l1$,$l1$Goldene Röhrlingsregel: rote Poren = nicht in den Korb ohne sichere Bestimmung. Nur gelbe Poren + mildes Fleisch + fehlender Selleriegeruch beim Anhängselröhrling sind unbedenklich (der zudem geschützt/selten ist).$l1$,$l1$123pilze, Wikipedia (Rubroboletus legaliae / Butyriboletus), AWL.ch, DGfM$l1$),
($l1$steinpilz$l1$,$l1$rubroboletus_satanas$l1$,$l1$hoch$l1$,array[$l1$Satansroehrling hat ROTE bis orangerote Poren; der Steinpilz hat NIE rote Poren (jung weiss, dann gelblich-oliv).$l1$,$l1$Satansroehrling-Fleisch blaut beim Anschnitt nur schwach bis maessig; Steinpilz-Fleisch bleibt komplett weiss und verfaerbt sich nicht.$l1$,$l1$Satansroehrling hat ein deutlich rotes, engmaschiges Stielnetz auf gelbem Grund (spaeter blutrot) am bauchig-knolligen Stiel; Steinpilz hat ein feines weisses bis braeunliches Netz.$l1$,$l1$Reifer/alter Satansroehrling riecht widerlich nach Aas; Steinpilz riecht angenehm pilzig-nussig.$l1$,$l1$Beide haben jung einen hellen, weisslich-graugruenen bis kalkweissen Hut - die helle Hutfarbe allein darf NIE zur Bestimmung dienen.$l1$]::text[],$l1$Entscheidend ist die Porenfarbe: rot/orange beim Satansroehrling, nie beim Steinpilz - plus das rote Stielnetz statt weissem Netz und das schwache Blauen statt gar keiner Verfaerbung.$l1$,$l1$Alter Satansroehrling stinkt nach Aas/Verwesung, Steinpilz riecht angenehm nussig-pilzig.$l1$,$l1$Beide in warmen Laubwaeldern auf Kalk unter Eiche/Buche - das Habitat trennt sie nicht zuverlaessig.$l1$,$l1$Beide olivbraunes Sporenpulver - kein praktisches Trennmerkmal.$l1$,$l1$Jeden Roehrling mit auch nur ansatzweise roten/orangen Poren grundsaetzlich stehen lassen - ein echter Steinpilz hat NIE rote Poren.$l1$,$l1$123pilze, AWL.ch (Pilzkurse Schweiz), Wikipedia (Satans-Roehrling), pilzbuch-pilzwelten.de$l1$),
($l1$butyriboletus_appendiculatus$l1$,$l1$rubroboletus_satanas$l1$,$l1$hoch$l1$,array[$l1$Anhaengselroehrling (Dickfussroehrling) hat GELBE Poren, der Satansroehrling rote bis orange Poren.$l1$,$l1$Anhaengselroehrling blaut nur schwach im gelben Fleisch und hat keinen Aasgeruch; Satansroehrling riecht im Alter widerlich nach Aas.$l1$,$l1$Anhaengselroehrling hat braunen, samtigen Hut; Satansroehrling jung hellen, kalkweiss bis weisslich-graugruenen Hut.$l1$,$l1$Anhaengselroehrling-Stiel ist gelb mit feinem gelbem Netz, oft mit wurzelndem Anhaengsel; Satansroehrling-Stiel rotgenetzt und knollig.$l1$,$l1$Beide wachsen auf Kalk im warmen Laubwald - die rote Porenfarbe ist das Sicherheitskriterium.$l1$]::text[],$l1$Anhaengselroehrling hat gelbe Poren und gelben Stiel, Satansroehrling rote Poren und rotgenetzten Stiel.$l1$,$l1$Satansroehrling riecht alt nach Aas, der Anhaengselroehrling angenehm pilzig.$l1$,$l1$Beide kalkliebend in warmen Eichen-/Buchenwaeldern - kein Trennmerkmal.$l1$,$l1$Beide olivbraunes Sporenpulver - nicht trennend.$l1$,$l1$Bei roten oder orangen Poren immer stehen lassen - gelbporige Dickfussroehrlinge sind essbar, rotporige sind tabu.$l1$,$l1$123pilze, AWL.ch (Vergleich rotporige Roehrlinge), pilzbuch-pilzwelten.de$l1$),
($l1$suillellus_luridus$l1$,$l1$rubroboletus_satanas$l1$,$l1$hoch$l1$,array[$l1$Netzstieliger Hexenroehrling blaut beim Anschnitt SCHNELL und intensiv tiefblau; Satansroehrling blaut nur schwach/verzoegert.$l1$,$l1$Netzstieliger Hexenroehrling hat einen olivgelben bis grau-braunen Hut; Satansroehrling jung einen hellen, kalkweiss-graugruenen Hut.$l1$,$l1$Beide haben rote/orangerote Poren UND ein rotes Stielnetz - die rote Porenfarbe trennt sie NICHT, nur Blauen-Geschwindigkeit, Hutfarbe und Geruch.$l1$,$l1$Satansroehrling riecht im Alter widerlich nach Aas; der Netzstielige Hexenroehrling riecht neutral-pilzig.$l1$,$l1$Der Netzstielige Hexenroehrling ist roh giftig/unvertraeglich und nur gut durcherhitzt essbar; der Satansroehrling bleibt auch gekocht giftig.$l1$]::text[],$l1$Heller weisslich-grauer Hut beim Satansroehrling vs. olivgelb-brauner Hut beim Hexenroehrling; Hexenroehrling blaut sofort intensiv, Satansroehrling nur schwach.$l1$,$l1$Satansroehrling alt nach Aas, Netzstieliger Hexenroehrling neutral-pilzig.$l1$,$l1$Beide auf Kalk unter Laubbaeumen - kein sicheres Trennmerkmal.$l1$,$l1$Beide olivbraun - nicht trennend.$l1$,$l1$Rotporige Roehrlinge nur essen, wenn zweifelsfrei als essbarer Hexenroehrling bestimmt UND gruendlich durcherhitzt - im Zweifel zur Pilzkontrolle (VAPKO).$l1$,$l1$123pilze, AWL.ch (Vergleich rotporige Roehrlinge), Wikipedia (Netzstieliger Hexen-Roehrling)$l1$),
($l1$flockenstieliger_hexenpilz$l1$,$l1$rubroboletus_satanas$l1$,$l1$hoch$l1$,array[$l1$Flockenstieliger Hexenroehrling hat KEIN Stielnetz, sondern rote Floeckchen/Punkte auf gelbem Stiel; Satansroehrling hat ein deutliches rotes Stielnetz - das ist das wichtigste Trennmerkmal.$l1$,$l1$Flockenstieliger Hexenroehrling blaut sofort und intensiv schwarzblau; Satansroehrling nur schwach.$l1$,$l1$Flockenstieliger Hexenroehrling hat braunen bis dunkelbraun-ziegelroten Hut; Satansroehrling jung hellen, kalkweiss-graugruenen Hut.$l1$,$l1$Satansroehrling riecht alt nach Aas; der Flockenstielige riecht angenehm pilzig.$l1$,$l1$Beide haben rote Poren - der Flockenstielige ist nur gut durcherhitzt essbar (roh giftig), der Satansroehrling bleibt giftig.$l1$]::text[],$l1$Stiel mit roten Floeckchen (KEIN Netz) und sofort intensives Schwarzblauen beim Flockenstieligen vs. rotes Stielnetz und schwaches Blauen beim Satansroehrling.$l1$,$l1$Satansroehrling alt nach Aas, Flockenstieliger angenehm pilzig.$l1$,$l1$Flockenstieliger waechst auch in sauren Nadelwaeldern; Satansroehrling streng auf warmen Kalk-Laubwald beschraenkt.$l1$,$l1$Beide olivbraun - nicht trennend.$l1$,$l1$Flockiger Stiel ohne Netz spricht fuer den essbaren Hexenroehrling; ein rotes Netz am Stiel ist ein Warnsignal Richtung Satansroehrling - im Zweifel verwerfen und durcherhitzen ist Pflicht.$l1$,$l1$123pilze, AWL.ch (Vergleich rotporige Roehrlinge), Wikipedia (Flockenstieliger Hexen-Roehrling), DGfM$l1$),
($l1$russula_vesca$l1$,$l1$russula_nobilis$l1$,$l1$mittel$l1$,array[$l1$Buchen-Speitaeubling schmeckt sofort EXTREM scharf/brennend; der Speisetaeubling schmeckt mild-nussig (Taeublingsregel: scharf = giftig).$l1$,$l1$Beim Speisetaeubling ist die Huthaut typisch zu kurz und laesst den Hutrand frei ('zu kurzer Mantel'); beim Buchen-Speitaeubling deckt sie den Rand.$l1$,$l1$Buchen-Speitaeubling hat lebhaft zinnoberrote Hutfarbe; Speisetaeubling eher fleischrot, weinrot bis braeunlich, oft fleckig ausgeblasst.$l1$,$l1$Lamellen des Speisetaeublings im Alter rostfleckig; beim Buchen-Speitaeubling rein weisslich bis blass cremegelb.$l1$,$l1$Beide haben einen weissen Stiel und wachsen im Buchenwald - nur der Geschmackstest trennt sicher.$l1$]::text[],$l1$Speisetaeubling mit charakteristisch zurueckgezogener Huthaut (freier Hutrand) und matterem Rotton; Buchen-Speitaeubling leuchtend zinnoberrot mit randdeckender Haut.$l1$,$l1$Buchen-Speitaeubling riecht suesslich-obstartig; Speisetaeubling fast geruchlos bis schwach nussig.$l1$,$l1$Beide bei Buche auf eher trockenen Boeden - Habitat trennt nicht.$l1$,$l1$Beide weissliches Sporenpulver - kaum trennend.$l1$,$l1$Bei roten Taeublingen IMMER ein Stueckchen Hutrand kauen und ausspucken - brennend scharf bedeutet giftig und gehoert nicht in den Korb.$l1$,$l1$123pilze, pilzbuch-pilzwelten.de (Buchenspeitaeubling/Speisetaeubling), Wikipedia (Taeublingsregel), DGfM$l1$),
($l1$russula_xerampelina$l1$,$l1$russula_queletii$l1$,$l1$mittel$l1$,array[$l1$Stachelbeer-Taeubling schmeckt EXTREM scharf (einer der schaerfsten Taeublinge); der Heringstaeubling mild (Taeublingsregel: scharf = giftig).$l1$,$l1$Heringstaeubling riecht typisch nach Hering/Fischlake (besonders in warmer Hand und im Alter); Stachelbeer-Taeubling riecht fruchtig nach Stachelbeerkompott.$l1$,$l1$Heringstaeubling-Fleisch braeunt/gilbt und gibt mit Eisensulfat eine gruene Reaktion; Stachelbeer-Taeubling nicht.$l1$,$l1$Stachelbeer-Taeubling hat purpurrot ueberhauchten, violett getoenten Stiel; Heringstaeubling oft rosa-roetlichen, spaeter braeunenden Stiel.$l1$,$l1$Beide wachsen bei Fichte - Geschmack und Geruch trennen sicher.$l1$]::text[],$l1$Heringstaeubling braeunt im Fleisch und am Stiel; Stachelbeer-Taeubling bleibt purpurrot-violett ohne Braeunung.$l1$,$l1$Heringstaeubling nach Fisch/Hering, Stachelbeer-Taeubling fruchtig nach Stachelbeerkompott.$l1$,$l1$Beide bei Fichte auf eher kalkhaltigem Boden - Habitat trennt nicht.$l1$,$l1$Heringstaeubling ockergelbes, Stachelbeer-Taeubling cremegelbes Sporenpulver.$l1$,$l1$Geschmackstest entscheidet: brennend scharf = giftiger Stachelbeer-Taeubling; mild plus Fischgeruch = essbarer Heringstaeubling.$l1$,$l1$123pilze, pilzbuch-pilzwelten.de (Stachelbeertaeubling/Heringstaeubling), DGfM, Wikipedia$l1$),
($l1$russula_paludosa$l1$,$l1$russula_queletii$l1$,$l1$mittel$l1$,array[$l1$Stachelbeer-Taeubling schmeckt anhaltend EXTREM scharf; Apfeltaeubling ist mild bzw. nur anfangs leicht scharf und wird mild (Taeublingsregel).$l1$,$l1$Apfeltaeubling hat blutrot/orangerot/kupferroten Hut; Stachelbeer-Taeubling dunkler purpur-violettrot.$l1$,$l1$Apfeltaeubling-Stiel weiss, oft schwach rosa angehaucht; Stachelbeer-Taeubling-Stiel deutlich violett-purpurrot ueberhaucht.$l1$,$l1$Stachelbeer-Taeubling riecht fruchtig nach Stachelbeerkompott; Apfeltaeubling unauffaellig.$l1$,$l1$Beide bei Nadelbaeumen (Fichte/Kiefer) - der Geschmack ist das Sicherheitskriterium.$l1$]::text[],$l1$Apfeltaeubling leuchtend blut-/orangerot mit fast weissem Stiel; Stachelbeer-Taeubling dunkler purpurviolett mit violett ueberlaufenem Stiel.$l1$,$l1$Stachelbeer-Taeubling fruchtig nach Stachelbeerkompott; Apfeltaeubling geruchsarm.$l1$,$l1$Apfeltaeubling oft an feuchten Stellen/Moorraendern bei Kiefer/Fichte; Stachelbeer-Taeubling bevorzugt Fichte auf Kalk.$l1$,$l1$Apfeltaeubling ockergelbes, Stachelbeer-Taeubling cremegelbes Sporenpulver.$l1$,$l1$Nur Taeublinge essen, die nach 30 s Kauen vollstaendig mild bleiben - anhaltende Schaerfe heisst giftig.$l1$,$l1$123pilze, pilzbuch-pilzwelten.de (Stachelbeertaeubling/Apfeltaeubling), AWL.ch$l1$),
($l1$russula_paludosa$l1$,$l1$russula_sardonia$l1$,$l1$mittel$l1$,array[$l1$Zitronenblaettriger Taeubling schmeckt sehr scharf (einer der schaerfsten); Apfeltaeubling wird mild (Taeublingsregel: scharf = giftig).$l1$,$l1$Zitronenblaettriger Taeubling hat leuchtend ZITRONENGELBE Lamellen; Apfeltaeubling cremeweisse bis ockergelbe Lamellen.$l1$,$l1$Zitronenblaettriger Taeubling hat purpurviolett-schwaerzlichen Hut und violetten Stiel; Apfeltaeubling blut-/orangeroten Hut mit fast weissem Stiel.$l1$,$l1$Zitronenblaettriger Taeubling weint bei feuchtem Wetter Tropfen an den Lamellen ('Traenen-Taeubling'); Apfeltaeubling nicht.$l1$,$l1$Beide bei Kiefer/Fichte - nur Geschmack und Lamellenfarbe trennen sicher.$l1$]::text[],$l1$Auffaellig zitronengelbe Lamellen und violetter Stiel beim Zitronenblaettrigen; Apfeltaeubling cremefarbene Lamellen und weisser Stiel.$l1$,$l1$Zitronenblaettriger Taeubling schwach fruchtig; Apfeltaeubling geruchsarm - Geruch trennt kaum, der Geschmack umso mehr.$l1$,$l1$Beide bei Kiefer auf sauren Boeden - Habitat trennt nicht.$l1$,$l1$Zitronenblaettriger Taeubling cremefarbenes, Apfeltaeubling ockergelbes Sporenpulver.$l1$,$l1$Zitronengelbe Lamellen unter violettem Hut plus scharfer Geschmack = giftig stehen lassen, nie mit mildem Apfeltaeubling verwechseln.$l1$,$l1$123pilze, pilzbuch-pilzwelten.de, Wikipedia (Zitronenblaettriger Taeubling), naturemobile$l1$),
($l1$russula_xerampelina$l1$,$l1$russula_sardonia$l1$,$l1$mittel$l1$,array[$l1$Zitronenblaettriger Taeubling schmeckt sehr scharf; Heringstaeubling mild (Taeublingsregel: scharf = giftig).$l1$,$l1$Heringstaeubling riecht nach Hering/Fischlake und braeunt im Fleisch; Zitronenblaettriger Taeubling riecht schwach fruchtig und braeunt nicht.$l1$,$l1$Zitronenblaettriger Taeubling hat leuchtend zitronengelbe Lamellen; Heringstaeubling cremeocker, spaeter braeunend.$l1$,$l1$Heringstaeubling reagiert mit Eisensulfat gruen; Zitronenblaettriger Taeubling nicht gruen.$l1$,$l1$Beide bei Kiefer/Fichte - Geschmack und Fischgeruch sind die Sicherheitskriterien.$l1$]::text[],$l1$Zitronenblaettriger Taeubling mit zitronengelben Lamellen und violettem Hut; Heringstaeubling braeunlich-rot mit braeunenden Lamellen und Stiel.$l1$,$l1$Heringstaeubling deutlich nach Fisch/Hering; Zitronenblaettriger Taeubling schwach fruchtig, nie fischig.$l1$,$l1$Beide bei Nadelbaeumen (Kiefer/Fichte) - Habitat trennt nicht.$l1$,$l1$Heringstaeubling ockergelbes, Zitronenblaettriger Taeubling cremefarbenes Sporenpulver.$l1$,$l1$Mild plus Fischgeruch = essbarer Heringstaeubling; scharf mit zitronengelben Lamellen = giftiger Zitronenblaettriger Taeubling.$l1$,$l1$123pilze, pilzbuch-pilzwelten.de, DGfM, Wikipedia$l1$),
($l1$lycoperdon_perlatum$l1$,$l1$scleroderma_citrinum$l1$,$l1$mittel$l1$,array[$l1$Schnitt-Test ist entscheidend: Flaschenstaeubling jung innen rein weiss und homogen-weich; Kartoffelbovist schon jung mit graustichigem, dann violettschwarz marmoriertem, hartem Inneren.$l1$,$l1$Kartoffelbovist hat eine dicke (bis 5 mm), zaehe, harte Aussenschale mit grober, schorfig-felderiger Oberflaeche; Staeubling hat duenne, weiche Haut mit feinen pyramidenfoermigen Stacheln/Warzen, die spaeter abfallen.$l1$,$l1$Kartoffelbovist riecht unangenehm metallisch/gummiartig; Flaschenstaeubling jung unauffaellig mild-pilzig.$l1$,$l1$Kartoffelbovist sitzt fast stiellos knollig am Boden; Flaschenstaeubling hat einen deutlich abgesetzten, schlanken sterilen Stielteil (Birnen-/Flaschenform).$l1$]::text[],$l1$Kartoffelbovist gelbbraun, hart, grob schorfig-felderig, ohne echten abgesetzten Stiel; Flaschenstaeubling weiss-grau mit feinen pyramidalen Stacheln und deutlich abgesetztem Stielteil.$l1$,$l1$Kartoffelbovist unangenehm metallisch-gummiartig; Flaschenstaeubling jung mild-pilzig, unauffaellig.$l1$,$l1$Kartoffelbovist auf saurem, magerem Waldboden, mykorrhizal an Baeumen (Eiche, Buche, Birke); Flaschenstaeubling auf Wald- und Wiesenboeden in Nadel- und Laubwald, an Wegraendern.$l1$,$l1$Reifebestimmung statt Abwurf: Kartoffelbovist hat schon bei halbreifen Stuecken braunschwarze Sporenmasse im Inneren; junger Flaschenstaeubling im Schnitt noch komplett weiss ohne dunkle Sporenmasse.$l1$,$l1$JEDEN runden Bovist VOR dem Essen laengs komplett durchschneiden: Ist das Innere nicht durchgehend rein weiss und homogen (dunkel marmoriert, graustichig oder hartschalig), wegwerfen - das ist der giftige Kartoffelbovist.$l1$,$l1$123pilze, DGfM, toxinfo.org, pilzbuch-pilzwelten.de, GiftnotrufZentrale$l1$),
($l1$calvatia_gigantea$l1$,$l1$scleroderma_citrinum$l1$,$l1$mittel$l1$,array[$l1$Verwechslung praktisch nur bei JUNGEN/kleinen Exemplaren: ausgewachsene Riesenboviste (15-50 cm) sind unverwechselbar, kleine junge aber kugelig und weisslich wie ein Bovist.$l1$,$l1$Riesenbovist im Schnitt jung gleichmaessig schneeweiss-watteartig weich; Kartoffelbovist im Schnitt schon jung dunkel/graustichig marmoriert.$l1$,$l1$Kartoffelbovist hat eine harte, dicke, zaehe Schale; Riesenbovist eine duenne, weiche, lederartige Huelle.$l1$,$l1$Kartoffelbovist riecht metallisch-unangenehm; junger Riesenbovist mild-pilzig.$l1$]::text[],$l1$Riesenbovist gross, weiss, glatt und weichschalig; Kartoffelbovist klein (3-10 cm), gelbbraun, hart und grob-felderig schorfig.$l1$,$l1$Kartoffelbovist unangenehm metallisch; junger Riesenbovist mild-angenehm.$l1$,$l1$Riesenbovist auf naehrstoffreichen, gedüngten Wiesen, Weiden, Gaerten und Brennnessel-Saeumen; Kartoffelbovist auf saurem Waldboden mykorrhizal bei Baeumen.$l1$,$l1$Kartoffelbovist im Schnitt frueh braunschwarz-sporig; Riesenbovist jung innen rein weiss ohne dunkle Sporenmasse - nur in diesem Zustand essbar.$l1$,$l1$Nur gross-weisse Boviste essen, die im Laengsschnitt KOMPLETT schneeweiss und homogen sind. Jede dunkle Marmorierung, gelbliche Verfaerbung oder harte Schale bedeutet entweder ueberreif (ungeniessbar) oder Kartoffelbovist (giftig).$l1$,$l1$123pilze, DGfM, VAPKO, GiftnotrufZentrale$l1$),
($l1$lycoperdon_perlatum$l1$,$l1$scleroderma_verrucosum$l1$,$l1$mittel$l1$,array[$l1$Der Duennschalige Kartoffelbovist hat - anders als der Dickschalige - einen deutlich ausgepraegten, gefurchten, sterilen Stielansatz mit Myzelstraengen, wodurch er dem gestielten Flaschenstaeubling aeusserlich aehnlicher und damit besonders verwechselbar ist.$l1$,$l1$Schnittfleisch des Kartoffelbovists wird schon jung graustichig bis dunkel marmoriert; Flaschenstaeubling jung rein weiss und homogen.$l1$,$l1$Kartoffelbovist-Schale lederzaeh, fein braunwarzig; Staeubling-Haut weich mit feinen, abfallenden pyramidalen Stacheln.$l1$,$l1$Kartoffelbovist riecht metallisch-unangenehm; junger Staeubling mild-pilzig.$l1$]::text[],$l1$Duennschaliger Kartoffelbovist gelbbraun, feinwarzig, mit deutlich gefurchtem sterilem Stielansatz; Flaschenstaeubling weiss-grau mit feinen Stacheln und glattem, abgesetztem Stielteil.$l1$,$l1$Kartoffelbovist metallisch-unangenehm; Flaschenstaeubling jung mild-pilzig.$l1$,$l1$Duennschaliger Kartoffelbovist auf sandigen Boeden in Heide, Laub- und Nadelwald, oft an Wegraendern; Flaschenstaeubling in Waeldern und auf Wiesen.$l1$,$l1$Kartoffelbovist im Schnitt frueh dunkelbraun-sporig; junger Staeubling noch weisses Fleisch ohne dunkle Sporenmasse.$l1$,$l1$Jeden kugeligen Pilz laengs aufschneiden: dunkles, marmoriertes oder violettschwarzes Inneres heisst Kartoffelbovist - nie essen. Nur durchgehend rein weisses, homogenes Inneres ist sicher.$l1$,$l1$123pilze, DGfM, wien.gv.at Konsumentenschutz, mushroom-toxin.de, GiftnotrufZentrale$l1$),
($l1$tricholoma_portentosum$l1$,$l1$tricholoma_equestre$l1$,$l1$hoch$l1$,array[$l1$Gruenling (giftig): Lamellen und Stielfleisch auffaellig schwefel- bis zitronengelb; Schwarzfaseriger Ritterling (essbar): Lamellen jung weiss, im Alter hoechstens schwach gelblich-gruen ueberlaufen, nie satt schwefelgelb.$l1$,$l1$Gruenling-Hut gelblich-olivbraun mit deutlichem gelbem Grundton; Schwarzfaseriger Ritterling silbergrau mit schwarzen radialen Faserstreifen, oft mit lila/gruenlichem Schimmer.$l1$,$l1$Beide wachsen bei Kiefern auf Sandboden - der Standort ist KEIN Unterscheidungsmerkmal; die Lamellen- und Stielfarbe ist ausschlaggebend.$l1$,$l1$Gruenling kann bei wiederholtem Verzehr groesserer Mengen (mehrere Mahlzeiten in wenigen Tagen) Rhabdomyolyse (Muskelzerfall) ausloesen - 2001 in Frankreich 12 Faelle, 3 Todesfaelle; daher als giftig eingestuft und in einigen Laendern geschuetzt.$l1$]::text[],$l1$Gruenling durchgehend gelblich, besonders die Lamellen schwefelgelb; Schwarzfaseriger Ritterling grau mit schwarzen Radialfasern und blassen, jung weissen Lamellen.$l1$,$l1$Beide mild mehlig bis gurkenartig - der Geruch unterscheidet sie NICHT zuverlaessig.$l1$,$l1$Beide bei Kiefern/Foehren auf mageren Sandboeden - daher hohe Verwechslungsgefahr; der Standort trennt sie nicht.$l1$,$l1$Beide weisses Sporenpulver - kein Unterscheidungsmerkmal.$l1$,$l1$Jeden gelblichen Ritterling mit schwefelgelben Lamellen aus dem Kiefernwald meiden - der Gruenling ist trotz frueherem Speisepilz-Status heute wegen dokumentierter toedlicher Muskelzerfall-Vergiftungen als giftig eingestuft.$l1$,$l1$DGfM, BfR (Bundesinstitut fuer Risikobewertung), VAPKO, Wikipedia Gruenling, fungiversum.de$l1$),
($l1$tricholoma_portentosum$l1$,$l1$tricholoma_pardinum$l1$,$l1$hoch$l1$,array[$l1$Tiger-Ritterling hat eine grob schuppig-genatterte, filzige Hutoberflaeche mit dunkelgrauen Schuppen auf hellerem Grund; Schwarzfaseriger Ritterling hat eine glatte, radial-faserig gestreifte, bei Naesse schmierige Hutoberflaeche OHNE grobe Schuppen.$l1$,$l1$Tiger-Ritterling oft kraeftiger/groesser (Hut bis 15 cm) mit dickem Stiel; Schwarzfaseriger Ritterling schlanker mit grau-faserigem Hut, oft mit lila/gruenlichem Ton.$l1$,$l1$Tiger-Ritterling waechst gern in Bergwaeldern auf Kalk bei Buche/Fichte; Schwarzfaseriger Ritterling typisch bei Kiefern auf saurem Sand.$l1$,$l1$Tiger-Ritterling verursacht heftiges Magen-Darm-Syndrom (Erbrechen/Durchfall schon nach 15-30 Min), schwere Vergiftungen moeglich; schon eine ausgespuckte Geschmacksprobe kann Beschwerden ausloesen.$l1$]::text[],$l1$Tiger-Ritterling grob schuppig-genattert/filzig mit Schuppenrasen; Schwarzfaseriger Ritterling glatt mit feinen schwarzen Radialfasern, kein Schuppenrasen.$l1$,$l1$Beide mehlig/gurkig - der Geruch trennt sie nicht und darf nicht zur Bestimmung verwendet werden.$l1$,$l1$Tiger-Ritterling bevorzugt Kalk-Bergwaelder bei Buche/Fichte; Schwarzfaseriger Ritterling bei Kiefern auf sauren Sandboeden.$l1$,$l1$Beide weisses Sporenpulver - kein Unterscheidungsmerkmal.$l1$,$l1$Graue Ritterlinge mit grob schuppig-genatterter Hutoberflaeche grundsaetzlich stehen lassen - der Tiger-Ritterling ist einer der haeufigsten schweren Pilzvergifter Mitteleuropas.$l1$,$l1$123pilze, DGfM, VAPKO, pilzbuch-pilzwelten.de, Wikipedia Tiger-Ritterling$l1$),
($l1$tricholoma_columbetta$l1$,$l1$tricholoma_pardinum$l1$,$l1$hoch$l1$,array[$l1$Weisser/Seidiger Ritterling ist rein weiss bis seidig glaenzend mit glatter Oberflaeche; Tiger-Ritterling ist grau bis graubraun mit groben dunklen Schuppen auf dem Hut.$l1$,$l1$Ein wirklich rein weisser, schuppenfreier Hut spricht klar gegen den Tiger-Ritterling; jede graue Toenung oder grobe Schuppe ist ein Warnsignal.$l1$,$l1$Weisser Ritterling kann am Stiel auf Druck blaugruenlich/rosa verfaerben, bleibt aber insgesamt weiss-seidig; Tiger-Ritterling ist von Grund auf grau gefaerbt und genattert-schuppig.$l1$,$l1$Tiger-Ritterling loest schweres Magen-Darm-Syndrom aus (Erbrechen/Durchfall nach 15-30 Min) - bei Grau-Toenung oder Schuppen niemals als Weissen Ritterling werten.$l1$]::text[],$l1$Weisser Ritterling rein weiss-seidig und glatt; Tiger-Ritterling grau mit grobem dunklem Schuppenrasen.$l1$,$l1$Weisser Ritterling mild bis schwach mehlig; Tiger-Ritterling mehlig/gurkig - der Geruch ist nicht entscheidend, Hutfarbe und Schuppung zaehlen.$l1$,$l1$Beide in Laub- und Bergwaeldern moeglich; der Standort trennt sie nicht zuverlaessig - Hutfarbe und Schuppung sind ausschlaggebend.$l1$,$l1$Beide weisses Sporenpulver - kein Unterscheidungsmerkmal.$l1$,$l1$WICHTIGER noch als der Tiger-Ritterling: rein weisse Ritterlinge koennen mit toedlichen weissen Knollenblaetterpilzen (Amanita) verwechselt werden - immer auf fehlende Knolle/Volva und Manschette pruefen. Nur makellos weisse, schuppenfreie Exemplare ohne Stielknolle gelten als Weisser Ritterling.$l1$,$l1$123pilze, DGfM, VAPKO, Wikipedia Ritterlinge$l1$),
($l1$tricholoma_portentosum$l1$,$l1$tricholoma_terreum$l1$,$l1$mittel$l1$,array[$l1$Schwarzfaseriger/Schneeritterling (essbar): Hut grau bis grauweiss mit eingewachsenen schwarzen RADIALFASERN, bei Feuchtigkeit deutlich schmierig-klebrig (Schleimhut), oft schwacher gelbgrünlicher Schimmer an Hutrand/Druckstellen.$l1$,$l1$Erd-Ritterling (hier als giftig gefuehrt): Hut mausgrau, fein FILZIG-SCHUPPIG (nicht radialfaserig, nie schmierig), trocken und matt, ohne Gelbgruenton.$l1$,$l1$portentosum-Fleisch/Lamellen koennen einen schwachen gelbgruenlichen Ton zeigen (v.a. an Druck/Schnitt) - NICHT als alleiniges Sicherheitsmerkmal verwenden, da variabel; terreum bleibt rein grau.$l1$,$l1$portentosum riecht/schmeckt mehlig-mild; terreum praktisch geruchlos und mild.$l1$,$l1$ACHTUNG Lebensgefahr in der grauen Ritterlings-Gruppe: der toedlich giftige Tiger-Ritterling (T. pardinum) sieht aehnlich aus (mehliger Geruch, grobe ziegelartige Schuppen, kraeftiger Wuchs) - bei jedem Zweifel ALLE grauen Ritterlinge stehen lassen.$l1$]::text[],$l1$Schneeritterling hat einen feucht-schmierigen (schleimigen) Hut mit eingewachsenen schwarzen Radialfasern und allenfalls schwachem Gelbgruenton; der Erd-Ritterling ist trocken, fein filzig-schuppig und rein mausgrau. Der Schleimhut bei Feuchtigkeit ist das auffaelligste Trennmerkmal.$l1$,$l1$portentosum mild mehlig; terreum nahezu geruchlos. Ein kraeftig mehliger Geruch bei einem grauen Ritterling ist KEINE Entwarnung - er passt auch zum toedlichen Tiger-Ritterling.$l1$,$l1$Beide bei Nadelbaeumen (v.a. Kiefer, auch Fichte) auf eher sandigen, kalkarmen Boeden im Herbst; der Standort trennt NICHT zuverlaessig.$l1$,$l1$Beide weisses Sporenpulver - nicht als Trennmerkmal nutzbar.$l1$,$l1$Graue Ritterlinge sind ein Anfaenger-Tabu: in dieser Farbgruppe stehen mehrere giftige bis toedliche Arten (inkl. Tiger-Ritterling T. pardinum). Nur sammeln, wenn der schmierige Hut MIT schwarzen Radialfasern eindeutig bestimmt ist und jeder Verdacht auf grobe Schuppen/kraeftigen Wuchs ausgeschlossen wurde - im Zweifel stehen lassen.$l1$,$l1$123pilze, pilzbuch-pilzwelten.de, DGfM, VAPKO, GiftnotrufZentrale (CH-Notruf 145)$l1$),
($l1$tricholoma_portentosum$l1$,$l1$tricholoma_saponaceum$l1$,$l1$mittel$l1$,array[$l1$Seifen-Ritterling (schwach giftig): typischer SEIFEN-/Waschpulver-Geruch - aber NICHT immer vorhanden (oft schwach, nach starkem Regen fast fehlend), daher kein Einzelkriterium.$l1$,$l1$Seifen-Ritterling: Fleisch verfaerbt sich bei Verletzung haeufig etwas roetlich, besonders im Stielgrund; Geschmack unangenehm bitter-mehlig.$l1$,$l1$Schneeritterling (essbar): mehlig-milder Geruch, KEINE deutliche Roetung des Fleisches; Hut feucht schmierig mit schwarzen Radialfasern.$l1$,$l1$Seifen-Ritterling-Hut sehr variabel grau bis grau-/gelbbraun, fein schuppig, matt - OHNE den schmierigen Schleimglanz des portentosum; Stiel oft spindelig/verdreht.$l1$,$l1$Im Zweifel Schnittprobe am Stielgrund + Geruchsprobe: roetendes Stielfleisch und/oder Seifen-/Waschlaugengeruch sind klare Warnsignale gegen Verzehr.$l1$]::text[],$l1$portentosum hat einen feucht-schmierigen, radialfaserig-schwarz gestreiften Hut mit allenfalls schwachem Gelbgruenton; saponaceum ist matt, trocken und stark farbvariabel (grau bis grau-/gelbbraun), fein schuppig, und sein Fleisch (v.a. Stielbasis) roetet beim Anschneiden.$l1$,$l1$Seifen-/Waschlaugengeruch spricht fuer saponaceum, mehlig-mild fuer portentosum. ACHTUNG: der Seifengeruch ist oft schwach oder fehlt (besonders nach Regen) - sein Fehlen ist KEINE Entwarnung.$l1$,$l1$saponaceum als Symbiosepilz in Misch- und Nadelwald (Aug-Nov); portentosum vor allem bei Kiefer/Fichte auf sandigem Boden - der Standort trennt nicht sicher.$l1$,$l1$Beide weisses Sporenpulver - kein Unterscheidungsmerkmal.$l1$,$l1$Stielbasis anschneiden und riechen: roetendes Fleisch und/oder Seifen-/Waschkuechengeruch bedeuten Seifen-Ritterling - nicht essen. Da der Seifengeruch fehlen kann, graue Ritterlinge generell nur bei 100% sicherer Bestimmung sammeln.$l1$,$l1$123pilze, pilzbuch-pilzwelten.de, DGfM, VAPKO, GiftnotrufZentrale (CH-Notruf 145)$l1$)
